    -- Translated interface, names and release notes
    ["**Brazilian Portuguese (ptBR), Traditional Chinese (zhTW), Korean (koKR), and Italian (itIT) localization.** The full interface, route notes, tips, achievements, and What's New now display in each of these languages on the matching client. With Spanish, German, French, Russian, and Simplified Chinese already supported, RetroRuns now speaks every language the game client offers."] = "**巴西葡萄牙文（ptBR）、繁體中文（zhTW）、韓文（koKR）和義大利文（itIT）本地化。** 對應語言的用戶端現在可以用各自的語言顯示完整介面、路線說明、提示、成就和“更新內容”。加上已支援的西班牙文、德文、法文、俄文和簡體中文，RetroRuns 現已支援遊戲用戶端提供的所有語言。",
    ["**Boss kills could vanish from Boss Progress after a reload.** Kills of certain bosses -- Blood Prince Council, Oregorger, Kromog, the Northrend Beasts, and a few dozen more -- unchecked themselves on the next login, sending the route back to a boss already dead for the week. Those kills now stay counted."] = "**重新載入後，已擊殺的首領可能從首領進度中消失。** 部分首領——血腥議會、礦吞、克羅莫格、北裂境巨獸以及其他數十個——的擊殺紀錄會在下次登入時取消勾選，使路線退回到本週早已擊殺的首領。現在這些擊殺會保留。",
    ["**Sample toasts on the settings pages could show boxes instead of text, or no title at all.** They now always use the game's standard typeface."] = "**設定頁面上的範例通知可能顯示方塊而非文字，或完全沒有標題。** 現在它們一律使用遊戲的標準字型。",
    ["**Teleporter destinations in the Skips details read in English on translated clients.** They now show the game's own names for those places."] = "**捷徑詳情中的傳送目的地在翻譯用戶端上顯示為英文。** 現在會顯示遊戲中這些地點的本地名稱。",
    ["**Item names in the transmog browser could flash in English before switching to your language.** They now render in your client's language right away."] = "**幻化瀏覽器中的物品名稱可能先短暫顯示英文，然後才切換為你的語言。** 現在會直接以你用戶端的語言顯示。",
    ["**\"Toaster\" stays in English in every language.** It is the feature's name, like RetroRuns itself."] = "**“Toaster”在所有語言中均保持英文。** 這是該功能的名稱，與 RetroRuns 一樣。",
    ["Baleroc, the Gatekeeper (lockout)"] = "巴勒羅克",
