    ["(Meta)"] = "（綜合）",
    ["(none)"] = "（無）",
    ["**Boss progress now tracks correctly on non-English clients in Mists of Pandaria raids.** On a client running in a non-English language, killing a boss in Mogu'shan Vaults, Heart of Fear, Terrace of Endless Spring, Throne of Thunder, or Siege of Orgrimmar did not register the kill or advance the route: the boss progress list, travel note, and map line stayed on the first boss no matter how far you had cleared. The Encounter Journal lookup used to match kills was reading at a difficulty those raids do not offer. English clients were unaffected and remain unchanged."] = "**現在，在《潘達利亞之謎》團隊副本中，非英語用戶端上的 首領 進度可以正確跟蹤。** 在以非英語運行的用戶端上，殺死魔古山寶庫、恐懼之心、無盡春天平台、雷霆王座或奧格瑞瑪之圍中的 首領 不會記錄擊殺或推進路線：首領 進度清單、旅行筆記和地圖線都會保留在第一個 首領 上，無論您清除了多遠。用於匹配擊殺的戰鬥日誌搜尋的讀取難度是這些團隊副本所不具備的。英語客戶未受影響且保持不變。",
    ["**Clicking a loot toast could open the appearances window on an unrelated page.** Every drop now opens to its own page, including shields, bows, guns, and wands your class cannot use -- the browser switches to a class that can see them and switches back when you close it. Appearances locked to the other faction say so and point at the preview instead of opening."] = "**左鍵點擊掉落提示時，過去可能會開啟無關頁面的外觀視窗。** 現在每件掉落都會開啟自己的頁面，包括目前職業無法使用的盾牌、弓、槍械和魔杖——外觀視窗會切換到能看到它們的職業，關閉時再切換回來。限定為另一陣營的外觀會予以說明並指向預覽，而不會開啟視窗。",
    ["**Expansion names display in the client's language.** The expansion headers and dropdowns follow what the game's own journal shows, which localizes them on some clients."] = "**資料片名稱會以用戶端語言顯示。** 資料片標題和下拉清單現在採用遊戲冒險指南中的名稱，因此會在支援的用戶端上自動本地化。",
    ["**Left-clicking a loot toast for gear your class cannot wear now shows the appearance.** The appearances browser opened to an empty page because its view is filtered to classes that can equip the item; it now switches the class filter to one that can view the drop, and switches it back when you close the window."] = "**左鍵點擊目前職業無法穿戴的裝備掉落提示時，現在會顯示對應外觀。** 外觀瀏覽器過去會開啟空白頁面，因為視圖只顯示能夠裝備該物品的職業。現在它會臨時切換到可查看該掉落的職業，並在關閉視窗時恢復原篩選。",
    ["**Localization fixes for Spanish clients.** Two Emerald Nightmare travel notes and twenty-one highlighted place names now render fully in Spanish, the Merithra and Vol'jin dialog triggers fire again, and the loot summary's chat rows (the \"From that kill\" heading, the \"New!\" tag, and the Mount, Pet, and Toy labels) are translated."] = "**西班牙文用戶端的本地化修正。** 兩則翡翠夢魘路線提示與二十一個醒目地名現在會完整顯示為西班牙文，Merithra 與 Vol'jin 的對話觸發再次正常運作，戰利品摘要中的聊天列（「本次擊殺」標題、「新！」標籤，以及坐騎、寵物和玩具標籤）也已翻譯。",
    ["**Localization support, starting with Spanish.** The groundwork is in place for RetroRuns to run in languages other than English: player-facing text now goes through a translation layer, and raid, wing, boss, and place names follow your game client's language. Spanish is the first language built on it, covering the interface and all route content on esES and esMX clients. More languages can now be added without further engine work. English clients are unchanged."] = "**本地化支援，首先推出西班牙文。** RetroRuns 現已具備使用英文以外語言運行的基礎：所有面向玩家的文字都會經過本地化層，團隊副本、分區、首領和地點名稱也會跟隨遊戲用戶端語言。西班牙文是首個支援的語言，覆蓋 esES 和 esMX 用戶端的介面及全部路線內容。今後可在無需繼續改動引擎的情況下新增更多語言。英文用戶端保持不變。",
    ["**Loot toasts now hold while you hover them.** Hovering a toast brings it back to full opacity and keeps it on screen for as long as the cursor stays on it, so there is time to read what dropped. Moving away resumes the fade from where it left off."] = "**滑鼠移到時，戰利品提示資訊會保持顯示。** 將滑鼠移到提示資訊上會使其恢復為完全不透明，並在光標停留期間一直顯示，讓你有足夠時間查看掉落內容。移開滑鼠後，淡出會從之前暫停的位置繼續。",
    ["**Loot toasts respond to clicks.** Right-click a toast to dismiss it. Ctrl-click to preview the item in the dressing room, whether it is an appearance, a mount, or a pet. Left-click opens the drop where it lives in your collection: appearances in the Appearances tab, mounts in the Mount Journal, pets in the Pet Journal, toys in the Toy Box. Opening a collection window is not possible during combat, so left-click waits until the fight is over; dismissing and previewing work at any time. The three gestures are listed in the toaster settings under Toaster Preview."] = "**戰利品通知現在支援點擊操作。** 右鍵點擊通知可將其關閉。按住 Ctrl 點擊可在試衣間預覽物品，無論它是外觀、坐騎還是寵物。左鍵點擊會在收藏中開啟該掉落物所在的位置：外觀位於「外觀」分頁，坐騎位於坐騎收藏，寵物位於寵物日誌，玩具位於玩具箱。戰鬥中無法開啟收藏視窗，因此左鍵點擊會等到戰鬥結束後再執行；關閉和預覽則可隨時使用。這三種操作列在 Toaster 設定的 Toaster 預覽下。",
    ["**Minimized mode comes to life.** Collapse the main panel to enable minimized mode. The main panel is replaced with a much smaller bar that shows an abbreviated version of every step-by-step travel note, along with a quick snapshot of current boss progress. Supported on all raids, all routes; Full, Skip, and LFR."] = "**最小化模式正式啟用。** 折疊主面板即可進入最小化模式。主面板會替換為更小的欄，顯示每條分步路線說明的縮略版本，以及目前首領進度的簡要概覽。所有團隊副本和路線均支援，包括完整、跳過和團隊搜尋器路線。",
    ["**On non-English clients, the route-selection popup could show rows of empty squares with no raid name.** The popup could appear before its text was filled in, rendering its prompt in a font that lacks the client language's characters; it now stays hidden until fully populated and always uses a font that covers the client's language. If a font fails to load, which can happen with replaced game fonts, the addon falls back to the game's own font instead of leaving text unreadable."] = "**在非英文用戶端上，路線選擇彈出視窗可能顯示一排空方塊，卻沒有團隊副本名稱。** 彈出視窗有時會在文字填充完成前出現，並使用不包含用戶端語言字元的字型。現在它會保持隱藏，直到內容全部填充完畢，並始終使用支援用戶端語言的字型。若字型載入失敗（替換遊戲字型時可能發生），插件會改用遊戲自帶字型，而不會留下無法閱讀的文字。",
    ["**On translated clients, the word above the SKIP button could overlap the \"Select Route\" prompt.** Hovering FULL or SKIP shows that button's word in your language above it, and on a longer word it ran into the prompt line. The dialog now leaves room for it."] = "**在翻譯版用戶端中，SKIP 按鈕上方的文字可能會與「選擇路線」提示重疊。** 將滑鼠移到 FULL 或 SKIP 上時，按鈕上方會以你的語言顯示對應文字；較長的文字可能會碰到提示行。對話框現在已預留足夠空間。",
    ["**Raids that share one lockout across two difficulties now recognize the week's progress from either side.** Entering the other difficulty of a lockout you had already progressed showed a fresh run and asked you to pick a route again; the addon now resumes your route, counts the kills you already have, and shows the run as complete when the lockout is finished."] = "**兩個難度共用同一進度的團隊副本，現在可以從任一難度識別本周進度。** 進入已推進進度的另一個難度時，插件過去會將其視為全新副本，並再次要求選擇路線。現在會繼續原有路線、計入已經擊敗的首領，並在該進度完成時將副本標記為完成。",
    ["**RetroRuns now speaks German, French, and Russian.** Full localization on deDE, frFR, and ruRU clients: the interface, every travel note and solo tip, boss and place names, achievement notes, sub-zone routing, dialog triggers, and the What's New window. Route tracking works the same as it does in English, including the steps that advance when you enter a specific part of a raid or when a boss speaks; quest, achievement, and place names carry Blizzard's official localized titles. English and Spanish clients are unchanged."] = "**RetroRuns 現已支援德語、法語和俄語。** deDE、frFR 和 ruRU 用戶端現已完整本地化，包括介面、全部路線說明和單刷提示、首領與地點名稱、成就說明、子區域路線、對話觸發器以及“新增內容”視窗。路線追蹤方式與英文用戶端相同，包括進入團隊副本特定區域或首領發言時自動推進的步驟；任務、成就和地點名稱均採用暴雪官方本地化名稱。英文和西班牙文用戶端保持不變。",
    ["**Simplified Chinese (zhCN) localization.** The full interface, route notes, tips, and What's New now display in Simplified Chinese on Chinese clients."] = "**簡體中文（zhCN）本地化。** 中國用戶端現在可以用簡體中文顯示完整介面、路線說明、提示和“更新內容”。",
    ["**The Achievements section now appears for every boss.** Bosses with no tracked achievements show the section with \"None\" rather than hiding it; the row opens the Achievements window."] = "**每個首領現在都會顯示成就區段。** 沒有追蹤成就的首領會顯示「無」，而不再隱藏該區段；點擊該列可開啟成就視窗。",
    ["**The Achievements window no longer changes width when switching raids.** It keeps the widest size it has needed so far and only its bottom edge moves, matching the transmog popup's behavior."] = "**切換團隊副本時，成就視窗不再改變寬度。** 它會保留曾經需要的最大寬度，只移動底部邊緣，與塑形彈出視窗的行為一致。",
    ["**The divider above the routing legend crowded the lines above and below it.** With several expansions listed, the supported-raids list grew into the space reserved for the legend, leaving the divider and its gem overlapping the last raid row and the legend text."] = "**路線圖例上方的分隔線與上下內容過於擁擠。** 當列出多個資料片時，受支援團隊副本清單會延伸到為圖例預留的空間，使分隔線及其寶石與最後一行團隊副本和圖例文字重疊。",
    ["**The Dragon Soul routing hint before Ultraxion now appears.** The step telling you to talk to Thrall to begin the encounter could never display."] = "**巨龍之魂中奧卓克希昂之前的路線提示現已正常顯示。** 提示你與索爾交談以開始戰鬥的步驟以前始終無法出現。",
    ["**The Firelands Glory reward rendered as plain text until the item cache primed.** The reward now resolves through the mount's spell link like every other Glory, so it links immediately."] = "**火焰之地“榮耀”成就獎勵在物品快取完成前會顯示為普通文字。** 現在該獎勵會像其他“榮耀”成就一樣透過坐騎法術連結解析，因此可以立即顯示為連結。",
    ["**The loot summary no longer misses drops when loot arrives a moment after the loot window closes.** On higher-latency pulls the summary could appear empty; it now waits briefly for the last items."] = "**當戰利品視窗關閉後不久到達時，戰利品摘要不再錯過掉落。** 在較高延遲的拉動中，摘要可能會顯示為空；現在它會短暫等待最後的項目。",
    ["**The minimized bar shows the way out when a run is complete.** Finishing a raid in minimized mode used to leave the bar showing only the RetroRuns wordmark. It now reads \"Raid Complete!\" — or the skip and Raid Finder equivalents — with an abbreviated exit tip beneath it."] = "**縮小列現在會在路線完成時顯示出口提示。** 過去以縮小模式完成團隊副本後，該列只會顯示 RetroRuns 字標。現在會顯示「團隊副本完成！」——或捷徑與團隊搜尋器的對應文字——並在下方顯示精簡的離場提示。",
    ["**The notification preview's Play button no longer runs into the notes beside it.** The button sizes to its own label and moves to its own line when the pair would reach the right-hand column."] = "**通知預覽中的“播放”按鈕不再與旁邊的說明重疊。** 按鈕會根據自身文字調整寬度；當按鈕和說明即將伸入右側欄時，按鈕會移到單獨一行。",
    ["**The panel now keeps one position across all characters.** The window's position has always been saved account-wide, but the game's own per-character frame memory was re-applying each character's last position over it, so every character ended up with the panel somewhere different. The saved position now wins everywhere: move it once and it stays there for the whole account."] = "**面板現在在所有角色上保持一個位置。** 視窗的位置始終在帳號通用內保存，但遊戲自己的每個角色幀內存正在重新套用每個角色的最後一個位置，因此每個角色最終都會在不同的地方出現面板。保存的位置現在無處不在：移動一次，整個帳號都會保留在那裡。",
    ["**The selected On/Off choice under \"Hide Blizzard Boss Banner:\" showed no underline.** The row's wide label pushed its buttons to a fractional pixel position where the hairline could vanish; positions now round to whole pixels and the underline uses the same pixel-grid handling as the dividers."] = "**「隱藏暴雪首領橫幅：」下方選取的開啟/關閉選項沒有顯示底線。** 該列較寬的標籤會將按鈕推到小數像素位置，細線因此可能消失；現在位置會四捨五入到整數像素，底線也採用與分隔線相同的像素格線處理。",
    ["**The skip route's target boss showed in English on translated clients.** The route picker's SKIP button names the boss the shortcut skips ahead to, and that name was printed from the addon's own English text rather than the game's. It now shows the name your client uses, on every raid with a skip route."] = "**在已翻譯用戶端上，跳過路線的目標首領名稱會顯示為英文。** 路線選擇器的SKIP按鈕會顯示捷徑通往的首領，但名稱來自插件自身的英文文字，而不是遊戲用戶端。現在所有帶跳過路線的團隊副本都會使用用戶端中的本地化名稱。",
    ["**The Sun King's Salvation tip in Castle Nathria was removed.**"] = "**已移除納撒亞城“太陽之王的救贖”提示。**",
    ["**The Toaster settings click legend now reads \"Left-Click: Collections\"** (was \"Left-Click: Open in Collections\"), in all languages."] = "**Toaster 設定的點擊圖例現在顯示「左鍵點擊：收藏」**（原為「左鍵點擊：在收藏中開啟」），所有語言皆已更新。",
    ["**The transmog browser could open filtered to another class.** A class chosen in the browser's dropdown, or reached by clicking a drop toast for gear your character cannot wear, was remembered permanently, so later visits kept showing that class, on that character and on every other one that shared its class. The choice now lasts only as long as the browser is open; opening it again shows the class you are playing."] = "**塑形瀏覽器可能會以其他職業的篩選狀態開啟。** 在瀏覽器下拉選單中選擇的職業，或透過點擊目前角色無法穿戴的裝備掉落提示進入的職業，會被永久記住，因此之後再次開啟時仍然顯示該職業，在該角色以及所有同職業的角色上都是如此。現在該選擇僅在瀏覽器開啟期間有效；再次開啟時會顯示你正在遊玩的職業。",
    ["**The transmog browser tracks the other faction's drops.** Faction-locked items were hidden entirely, but the game grants the opposite faction's appearance when its counterpart drops for you, so they are collectible. They appear in their own block at the bottom of each boss's list, tagged with the faction they belong to, and light up as you collect them. The needed counts still cover only what your character can loot."] = "**塑形瀏覽器現在會追蹤另一陣營的掉落。** 陣營限定物品此前會被完全隱藏，但當對應物品掉落時，遊戲也會解鎖另一陣營的外觀，因此這些物品同樣可以收集。它們現在會顯示在每個首領清單底部的獨立區域，並標注所屬陣營；收集後也會亮起。需求數量仍只統計目前角色能夠拾取的物品。",
    ["**The transmog window no longer shows a scrollbar when a boss's loot list fits.** A scrollbar, and a clipped travel button, appeared on bosses with a weapon-token footnote even when the list fit."] = "**當 首領 的戰利品清單適合時，塑形視窗不再顯示捲軸。** 即使清單適合，捲軸和剪輯的旅行按鈕也會出現在帶有武器標記腳注的 首領 上。",
    ["**The vendor travel button in the transmog window uses the correct plane icon and no longer sits under the scrollbar.**"] = "**塑形視窗中的商人旅行按鈕現在使用正確的飛機圖示，並且不再被捲軸遮擋。**",
    ["**The Volcanius marker in Vault of the Incarnates is a plain point of interest.** It was a pulsing ring of the kind that turns gray and ticks itself off once you pass it, but that kill cannot be detected, so the ring never resolved."] = "**洪荒化身牢獄中的沃爾卡尼烏斯標記現在是普通興趣點。** 它之前使用經過後變灰並自動完成的脈衝圓環，但該擊殺無法被偵測，因此圓環始終不會完成。",
    ["**The Wrath of the Lich King raids join RetroRuns.** All nine raids now have full routing and transmog tracking: Naxxramas, The Eye of Eternity, The Obsidian Sanctum, Onyxia's Lair, Vault of Archavon, Ulduar, Trial of the Crusader, Icecrown Citadel, and The Ruby Sanctum. Every raid carries step-by-step routing, boss progress, tier sets, special drops, achievements, and exit directions at every difficulty the raid offers. Icecrown Citadel is guided end to end across all twelve bosses for both factions, with the gunship and Deathbringer Saurfang approaches routed separately for Alliance and Horde. Valithria Dreamwalker is optional, and the guide follows players who run past her, picking up at Sindragosa; turn back for her and the route follows you back, and the run reads as complete once the Lich King falls either way. Ulduar offers guidance through each hard-mode available, along with hard-mode loot tracking in the transmog browser. Trial of the Crusader and Icecrown Citadel field a different encounter depending on your faction, and the boss list, route, and notes follow the one you actually fight."] = "**《巫妖王之怒》的團隊副本已加入RetroRuns。** 9個團隊副本現已全部支援完整路線引導和塑形追蹤：納克薩瑪斯、永恆之眼、黑曜聖所、奧妮克希亞的巢穴、亞夏梵穹殿、奧杜亞、十字軍試煉、冰冠城塞和晶紅聖所。每個團隊副本都包含逐步路線、首領進度、套裝、特殊掉落、成就以及所有可用難度的離場指引。冰冠城塞為聯盟和部落完整引導全部12個首領，並分別提供炮艇戰和死亡使者薩魯法爾的陣營路線。踏夢者瓦莉絲瑞雅為可選首領：若直接繞過她，路線會從辛德拉苟莎繼續；若返回完成她的戰鬥，路線也會隨之返回。無論哪種方式，擊敗巫妖王後都會將本次副本標記為完成。奧杜亞提供所有可用困難模式的指引，並在塑形瀏覽器中追蹤困難模式掉落。十字軍試煉和冰冠城塞會根據陣營出現不同戰鬥，首領清單、路線和提示會顯示你實際面對的版本。",
    ["**Toaster settings page layout holds up in every language.** The header wraps inside the frame instead of running past it, and the explainer text, click-gesture legend, and loot-summary preview no longer overlap the sample toasts."] = "**Toaster 設定頁面的版面現在能適應所有語言。** 標題會在框架內自動換行，不再超出邊界；說明文字、點擊操作圖例和戰利品摘要預覽也不再與範例通知重疊。",
    ["**Two boss names were spelled differently than the game spells them.** Tomb of Sargeras travel notes read \"Kil'Jaeden\" (the game uses \"Kil'jaeden\") and a Sanctum of Domination note read \"the Tarragrue\" mid-sentence where the boss is \"The Tarragrue\"."] = "**兩個首領名稱的拼法與遊戲內不同。** 薩格拉斯之墓的路線提示寫成「Kil'Jaeden」（遊戲內為「Kil'jaeden」），統御聖所的一則提示則在句中寫成「the Tarragrue」，但首領名稱是「The Tarragrue」。",
    ["10 Player only"] = "僅限 10 人",
    ["25 Player Heroic only"] = "僅限 25 人英雄難度",
    ["25 Player only"] = "僅限 25 人",
    ["7th Legion Gryphon"] = "第七軍團獅鷲獸",
