    ["|cff888888  -> Redeem at |r|c%s%s|r|cff888888 vendor: |r|c%s%s|r|cff888888 (|r|cffffffff%s|r|cff888888)|r"] = "|cff888888 -> 在 |r|c%s%s|r|cff888888 商人處兌換： |r|c%s%s|r|cff888888 (|r|cffffffff%s|r|cff888888)|r",
    ["|cff999999(That loot list is from an earlier lockout and is no longer available.)|r"] = "|cff999999（這份戰利品清單來自之前的副本進度，現已不可用。）|r",
