    ["|cffaaaaaav%s loaded. Type |r|cffffffff/rr help|r|cffaaaaaa for commands.|r"] = "|cffaaaaaa已載入 v%s。輸入 |r|cffffffff/rr help|r|cffaaaaaa 查看指令。|r",
