    ["|cffF259C7RETRO|r|cff4DCCFFRUNS|r  Raid Skips"] = "|cffF259C7RETRO|r|cff4DCCFFRUNS|r  團隊副本捷徑",
    ["|cffF259C7RETRO|r|cff4DCCFFRUNS|r  Transmog"] = "|cffF259C7RETRO|r|cff4DCCFFRUNS|r  塑形",
    ["|cffF259C7Skip:|r "] = "|cffF259C7跳過：|r ",
    ["|cffff8000Wowhead|r"] = "|cffff8000Wowhead|r",
    ["|cffff9333  -> No covenant detected|r|cff888888 -- align to redeem weapon tokens.|r"] = "|cffff9333  -> 未偵測到誓盟|r|cff888888——加入誓盟後才能兌換武器代幣。|r",
    ["|cffff9333Routing data not yet captured for this raid.|r"] = "|cffff9333尚未收錄這個團隊副本的路線資料。|r",
    ["%s Tier"] = "%s 階級",
