    ["Akama"] = "阿卡瑪",
    ["Barnes"] = "巴奈斯",
    ["King Llane"] = "萊恩國王",
    ["Warchief Blackhand"] = "大酋長黑手",

    ["**Collected items are dimmed in the transmog browser.** An item you have finished with now shows its name in gray rather than white, so the rows still worth your time stand out. An item counts as finished when every difficulty it drops at is collected."] = "**已收集的物品會在塑形瀏覽器中變暗。** 已完成收集的物品名稱現在會由白色變成灰色，讓仍值得注意的列更醒目。當該物品在所有會掉落它的難度下都已收集時，就會視為完成。",
    ["**Direct routes to a raid's final boss.** Some legacy raids allow the player to bypass the raid, and walk directly to the final boss. Examples include Kael'thas Sunstrider in The Eye and Lady Vashj in Serpentshrine Cavern. Unlike modern raid skips, these aren't tied to quest completion. Where one exists, the load window offers it alongside the full clear, and your choice is remembered for the week."] = "**直達團隊副本最終首領的路線。** 一些舊團隊副本允許玩家略過大部分流程，直接前往最終首領。例如風暴核心的凱爾薩斯·逐日者和毒蛇神殿洞穴的瓦許女士。與現代團隊副本捷徑不同，這些路線不需要完成任務。若某個團隊副本有這種路線，載入視窗會將它與完整清除路線一起提供，並在本週內記住你的選擇。",
    ["**Global POIs.** Useful fixtures such as repair vendors, quartermasters, etc. can now show on the raid map at all times, not only while a particular boss is your next objective. Vendors in Black Temple and Karazhan added to start, but more to come with the tooling now built."] = "**全域興趣點。** 修理商人、軍需官等實用設施現在可以隨時顯示在團隊副本地圖上，不再只有某個特定首領是下一個目標時才出現。首批加入的是黑暗神廟和卡拉贊的商人；相關工具已經完成，之後還會繼續增加。",
    ["**Hard-mode and opposite-faction drops fold into their own sections.** In the transmog browser, hard-mode-only drops (Ulduar) and the other faction's appearances (Trial of the Crusader) no longer run inline with the boss's loot list. Each now sits in its own collapsible section -- \"Hard Mode\", and \"Horde Appearances\" or \"Alliance Appearances\" depending on your character -- below the main list, collapsed until you expand it."] = "**困難模式和對立陣營掉落會收合到各自區域。** 在塑形瀏覽器中，僅限困難模式的掉落（奧杜亞）以及另一陣營的外觀（十字軍試煉）不再直接混在首領掉落清單中。它們現在分別位於主清單下方的可收合區域 -- 「困難模式」，以及依你的角色顯示的「部落外觀」或「聯盟外觀」 -- 預設收合，直到你主動展開。",
    ["**Icecrown Citadel's route could stall at The Spire on translated clients.** The step's location check only matched the English area name, so German, Spanish, French, Russian, and Simplified Chinese clients never saw it advance. It now matches each client's own name."] = "**在翻譯客戶端中，冰冠城塞的路線可能會卡在尖塔。** 該步驟的位置檢查只比對英文區域名稱，因此德文、西班牙文、法文、俄文和簡體中文客戶端都無法看到它繼續推進。現在會比對各客戶端自己的區域名稱。",
    ["**Loot-toast clicks could leave the Appearances window drawing the wrong models.** Clicking a toast for an item your class cannot wear switches the wardrobe to a class that can; the window then kept the previous class's models under the new list until it was closed and reopened. It now redraws correctly."] = "**點擊掉落 Toaster 可能讓外觀視窗顯示錯誤的模型。** 點擊目前職業無法穿戴的物品 Toaster 時，衣櫃會切換到能穿戴該物品的職業；但在關閉並重新開啟視窗之前，新清單下方仍會保留上一個職業的模型。現在會正確重新繪製。",
    ["**Section labels are now cyan.** The green and yellow section headings (Traveling, Achievements, Boss Encounter, Special Loot, Transmog Needed, Boss Progress, Trash Drops) now use the branded cyan instead."] = "**區域標籤現在改為青色。** 原本使用綠色和黃色的區域標題（前往路線、成就、首領戰、特殊戰利品、尚缺塑形、首領進度、小怪掉落）現在統一使用 RetroRuns 的品牌青色。",
    ["**The Burning Crusade raids join RetroRuns.** All eight raids now have full routing and transmog tracking: Karazhan, Gruul's Lair, Magtheridon's Lair, Serpentshrine Cavern, The Eye, The Battle for Mount Hyjal, Black Temple, and Sunwell Plateau. Every raid carries step-by-step routing, boss progress, tier tokens resolved to each class's pieces, battle pets, and exit directions. Everything is translated in all nine supported languages."] = "**《燃燒的遠征》團隊副本加入 RetroRuns。** 現在全部 8 個團隊副本都擁有完整路線與塑形追蹤：卡拉贊、戈魯爾之巢、瑪瑟里頓的巢穴、毒蛇神殿洞穴、風暴核心、海加爾山之戰、黑暗神廟和太陽之井高地。每個團隊副本都提供逐步路線、首領進度、可對應到各職業套裝部件的套裝代幣、戰寵以及出口指引。所有內容都已翻譯為 9 種支援的語言。",
    ["**The Transmog Needed summary takes up less space.** The [click to browse] hint now sits next to the heading instead of at the end of the counts, and the current difficulty shows as shorthand -- \"25H\" rather than \"25 Player (Heroic)\"."] = "**「尚缺塑形」摘要占用的空間更少。** [點擊瀏覽] 提示現在位於標題旁，而不是放在計數末尾；目前難度也改用縮寫顯示 -- 以「25H」取代「25人（英雄）」。",
    ["**The transmog window could grow upward after being moved.** Once dragged, expanding a section or switching bosses resized it from the center instead of downward from a fixed top edge."] = "**塑形視窗在移動後可能會向上增長。** 視窗一旦被拖曳，展開區域或切換首領時會從中心調整大小，而不是以固定的頂部邊緣向下延伸。",
    ["**Trash drops in the transmog browser.** Appearances that come off a raid's trash rather than a boss now have their own section, shown below whichever raid is selected. The section collapses to a single \"Trash Drops (collected/total)\" heading you can expand when you want it. Each row is tagged with how the item binds (BoP vs. BoE), and a BoE piece sitting in your bags is flagged as such so you don't miss it. Summary collection counter displays yellow until every appearance is collected, and green at 100%."] = "**塑形瀏覽器新增小怪掉落。** 來自團隊副本小怪而非首領的外觀現在有自己的區域，顯示在目前選取的團隊副本下方。此區域可收合成單一「小怪掉落（已收集/總數）」標題，需要時再展開。每一列都會標示物品的綁定方式（BoP 或 BoE）；如果你的背包裡已有一件 BoE 物品，也會特別標記，避免漏掉。彙總收藏計數在所有外觀收集完成前顯示為黃色，達到 100% 後變為綠色。",

    ["Ayamiss"] = "阿亞米斯",
    ["Destroy Egg"] = "摧毀龍蛋",
    ["Fankriss"] = "范克里斯",
    ["Orb of Domination"] = "統御寶珠",
    ["Razorgore"] = "拉佐格爾",
    ["Suppression Devices"] = "壓制裝置",
    ["Vaelastrasz"] = "瓦拉斯塔茲",

    ["**Assorted display fixes.** Loot lines up in proper columns, a boss's ordinary loot no longer sorts above its tier list, rows that looked identical are told apart, loot toasts respond to clicks during combat, and travel buttons say \"Zone out first\" rather than placing a waypoint that cannot be routed to."] = "**多項顯示問題修正。** 戰利品現在會正確按欄對齊，首領的一般戰利品不再排到T套裝列表上方，看起來相同的列會被區分，戰鬥中也可以點擊戰利品通知；旅行按鈕會顯示「請先離開副本」，而不是放置一個無法規劃路線的路徑點。",
    ["**Each faction's tier piece and its twin share one row** in the raids where every piece has a counterpart, with your own faction first and a marker for each version, so you can tell which of the two you still need."] = "**每個陣營的T套裝部位與其對應版本共用一列** 在每件物品都有另一陣營對應版本的團隊副本中，會先顯示你自己的陣營，並為兩個版本分別顯示標記，方便看出還缺哪一個。",
    ["**Loot rows could show the wrong name color**, most often in the Wrath raids, where a row whose markers said collected still rendered its name gray."] = "**戰利品列可能顯示錯誤的名稱顏色**，這種情況在《巫妖王之怒》團隊副本中最常見：即使列內標記顯示已收集，名稱仍會顯示為灰色。",
    ["**Optional bosses can be skipped.** A boss the route can bypass is marked as optional on the panel and in the Boss Progress list, and its encounter row offers a Skip Boss button. Skipping asks for confirmation first, because routing stays down for the rest of that lockout, and then sends you on to the next boss. The run finishes with a reminder that you can still go back and kill anything you skipped."] = "**可選首領現在可以跳過。** 路線可以繞過的首領會在面板與首領進度列表中標記為可選，其首領戰列也會提供「跳過首領」按鈕。跳過前會先要求確認，因為本次副本鎖定期間將不再提供路線指引；確認後會繼續前往下一個首領。本次通關結束時會提示：你仍然可以回頭擊殺跳過的首領。",
    ["**Redemption hints point at the right place.** Trial of the Crusader names the pieces your Trophies actually buy, and Siege of Orgrimmar no longer sends Alliance players to the Horde vendor's spot."] = "**兌換提示現在會指向正確位置。** 十字軍試煉會正確顯示你的獎盃實際可以購買哪些部位，圍攻奧格瑪也不再把聯盟玩家引導到部落商人的位置。",
    ["**Route notes advance promptly after fights the game reports oddly**, instead of waiting until you walk somewhere."] = "**遊戲以異常方式回報戰鬥結果時，路線說明也會及時推進**，不再等到你走到其他位置才更新。",
    ["**Several raids were missing appearances entirely.** Trash and shared boss drops across Siege of Orgrimmar, Naxxramas and Throne of Thunder never appeared in the browser, so they read as uncollectable however many times you cleared the raid. All of them now show."] = "**多個團隊副本曾完全缺少外觀。** 圍攻奧格瑪、納克薩瑪斯與雷霆王座中的小怪掉落及首領共用掉落從未出現在瀏覽器中，因此無論通關多少次都顯示為不可收集。現在這些外觀都會顯示。",
    ["**The Classic raids are in.** Molten Core, Blackwing Lair, Ruins of Ahn'Qiraj and Temple of Ahn'Qiraj each come with full routing, loot, tier sets and trash drops, so the addon now guides you from Classic through Dragonflight."] = "**經典版團隊副本已加入。** 熔火之心、黑翼之巢、安其拉廢墟與安其拉神廟均已提供完整路線、戰利品、T套裝與小怪掉落，因此插件現在可以從經典版一路引導到《巨龍崛起》。",
    ["**The transmog browser now covers dungeons.** A new Type selector switches between Raids and Dungeons; every legacy dungeon from Classic through Dragonflight is browsable with its bosses, loot, mounts, pets and toys -- 123 dungeons in all. Appearances track per difficulty where the game varies them."] = "**塑形瀏覽器現在也涵蓋地城。** 新增「類型」選擇器可在團隊副本與地城之間切換；從經典版到《巨龍崛起》的所有舊地城都可瀏覽，包括首領、戰利品、坐騎、寵物與玩具 -- 共123個地城。若遊戲依難度區分外觀，外觀也會依難度分別追蹤。",
    ["**The transmog browser reads more clearly.** Item names follow the same color key as their difficulty markers, tier is set apart from ordinary loot and always leads the list, legendaries sit in their own block, and gear only one class can wear says so."] = "**塑形瀏覽器現在更清楚。** 物品名稱使用與難度標記相同的顏色規則，T套裝與一般戰利品分開並始終排在列表最前，傳說物品單獨成區，僅限一個職業穿戴的裝備也會明確標示。",
    ["**Tier rows tell you more.** They show which specializations a piece can be handed to, the full upgrade chain where one exists, and any appearance a piece can be traded up to. The explanation beneath a tier list now folds away when you do not want it."] = "**T套裝列現在會顯示更多資訊。** 它們會顯示該部位可交給哪些專精、存在時的完整升級鏈，以及該部位可以繼續兌換成的任何外觀。不需要時，現在可以收合套裝列表下方的說明。",
    ["**Tokens now tell you where to take them.** Tier tokens that cannot simply be right-clicked, and the omnitokens some bosses drop in place of a fixed piece, show a hint under the boss that drops them: the NPC to visit, what the turn-in costs, and a travel button where one can be reached. Icecrown Citadel's map marker points at the quartermaster who serves your own class."] = "**徽記現在會告訴你該去哪裡兌換。** 無法直接按右鍵使用的套裝徽記，以及部分首領用來替代固定部位掉落的萬用徽記，會在掉落它們的首領下方顯示提示：要拜訪的NPC、兌換所需費用，以及在可抵達時提供旅行按鈕。冰冠城塞的地圖標記會指向負責你目前職業的軍需官。",

    ["**Assorted browser display fixes.** Loot lines up in proper columns, tier lists no longer sit double-spaced, a boss's ordinary loot no longer sorts above its tier list, rows that looked identical are told apart, and gear several classes can wear names the one you are looking at."] = "**瀏覽器的多項顯示問題修正。** 戰利品現在會正確按欄對齊，T套裝列表不再出現雙倍行距，首領的一般戰利品不再排到T套裝列表上方，看起來相同的列會被區分，多個職業都能穿戴的裝備也會標明你目前查看的職業。",
    ["**Smaller fixes.** Travel buttons say \"Zone out first\" rather than placing a waypoint that cannot be routed to, loot toasts respond to clicks during combat and open the right class's page, the Encounter Journal no longer redraws over itself, and row dividers no longer vanish at some window scales."] = "**小幅修正。** 旅行按鈕會顯示「請先離開副本」，而不是放置一個無法規劃路線的路徑點；戰鬥中也可以點擊戰利品通知，並會開啟正確職業的頁面；冒險指南不再自我重繪；列分隔線在某些視窗縮放下不再消失。",
    ["**The Classic raids are in, and that completes the roster.** Molten Core, Blackwing Lair, Ruins of Ahn'Qiraj and Temple of Ahn'Qiraj each come with full routing, loot, tier sets and trash drops. With them, every legacy raid in the game is now covered -- Classic through Dragonflight, all 51, every one of them walked and routed."] = "**經典版團隊副本已加入，名單就此完整。** 熔火之心、黑翼之巢、安其拉廢墟與安其拉神廟均已提供完整路線、戰利品、T套裝與小怪掉落。至此，遊戲中的每一個舊團隊副本都已涵蓋 -- 從經典版到《巨龍崛起》，全部51個，每一個都實地走過並規劃了路線。",
    ["**The transmog browser now covers dungeons.** A new Type selector switches between Raids and Dungeons, and every legacy dungeon from Classic through Dragonflight is there to browse boss by boss -- 123 dungeons in all, with appearances tracked per difficulty where the game varies them. Dungeons are browsing only for now; full guided routing, like the raids have, is coming soon. Probably."] = "**塑形瀏覽器現在也涵蓋地城。** 新增「類型」選擇器可在團隊副本與地城之間切換，從經典版到《巨龍崛起》的所有舊地城都可依首領逐一瀏覽 -- 共123個地城；若遊戲依難度區分外觀，外觀也會依難度分別追蹤。目前地城僅支援瀏覽，像團隊副本那樣的完整路線指引即將推出。大概吧。",

    -- Route content translations
    ["%s & %s"] = "%s & %s",
    ["%s Reputation"] = "%s聲望",
    ["%s Tier %s"] = "%s T%s",
    ["(optional)"] = "（可選）",
    ["(skipped)"] = "（已跳過）",
    ["/reload if stuck"] = "/如果卡住則重新載入",
    ["1"] = "1",
    ["1. Kill Baltharus"] = "1. 擊殺巴爾薩魯斯",
    ["1. When he's threatening to roll left, strafe right (and vice versa). You get 8-10 seconds after he emotes. 2. Stand by the front (armor plate), pulling enemies to you and killing them near the armor plate. 3. Kill ^Hideous Amalgamation^ on the armor to pry up the armor plates. 4. Prying up an armor plate exposes a ^Burning Tendon^. Kill it to advance. Doing this 3x will end the fight."] = "1. 當他威脅要向左翻滾時，向右掃射（反之亦然）。當他表現出情緒後，你有 8 到 10 秒的時間。 2.站在最前面（裝甲板），將敵人拉向你並殺死裝甲板附近的敵人。 3.殺死裝甲上的^Hideous Amalgamation^來撬起裝甲板。 4. 撬起裝甲板會暴露出^Burning Tendon^。殺掉它才能前進。執行此操作 3 次即可結束戰鬥。",
    ["2"] = "2",
    ["2. Kill Saviana"] = "2. 擊殺塞維婭娜",
    ["3"] = "3",
    ["3. Kill Zarithrian"] = "3. 擊殺扎里斯里安",
    ["^Immerseus^ alternates between phases several times. Phase1: Hit the boss. Phase2: Kill black blobs, heal blue ones if you can. The more killing/healing, the faster the fight."] = "^Immerseus^ 在各個階段之間交替多次。第一階段：擊中首領。第二階段：殺死黑色斑點，如果可以的話治愈藍色斑點。擊殺/治療越多，戰鬥就越快。",
    ["^Mythic^-- Just nuke the boss. ^Heroic^/^Normal^: Kill trash to fill the energy bar. Eventually, (3) ^Unstable Core^ will drop. Pick them up and carry each of them towards the boss, and use the Extra Action Button to throw them. After doing this 3 times, the boss will spawn."] = "^Mythic^-- 用核武器攻擊 首領。 ^Heroic^/^Normal^：殺死小怪以填充能量條。最終，(3) ^Unstable Core^ 將掉落。拿起它們並將它們帶到首領那裡，然後使用額外快捷鍵將它們扔掉。這樣做3次後，首領就會出現。",
    ["Action Button in Beam"] = "光束中的操作按鈕",
    ["After a brief dialog, kill ^Raszageth the Storm-Eater^!"] = "簡短對話後，殺死 ^Raszageth the Storm-Eater^！",
    ["After activating the ^Titan Console^, kill several waves of adds from the previous room to unlock the door to the next room."] = "啟動^Titan Console^後，殺死前一個房間的幾波小怪，以解鎖下一個房間的門。",
    ["After arriving at ^The Torment Chambers^, follow the path to ^Soulrender Dormazain^."] = "到達^The Torment Chambers^後，沿著路徑前往^Soulrender Dormazain^。",
    ["After arriving back in ^Halls of the Faithful^, follow the path all the way around to ^Artificer Xy'mox^. Kill the trash, and ^Prince Renathal^ will show up to open the gate."] = "返回 ^Halls of the Faithful^ 後，沿著路徑一路前往 ^Artificer Xy'mox^。殺死小怪，^Prince Renathal^ 就會出現並開啟大門。",
    ["After arriving back in ^The Grand Walk^, follow the path up to where you killed ^Shriekwing^. This time, take the path right/south to end up in ^Halls of the Faithful^."] = "返回 ^The Grand Walk^ 後，沿著路徑前往殺死 ^Shriekwing^ 的地方。這次，沿著右/南路徑到達 ^Halls of the Faithful^。",
    ["After arriving back in Antorus, follow the path to the left to reach ^Portal Keeper Hasabel^."] = "回到安托魯斯後，沿著左邊的路徑到達^Portal Keeper Hasabel^。",
    ["After arriving back in the ^Ring of Containment^, head straight ahead towards the map exit labeled ^The Oblivion Door^."] = "回到 ^Ring of Containment^ 後，徑直朝標有 ^The Oblivion Door^ 的地圖出口走去。",
    ["After arriving back on the ^Wyrmrest Summit^, talk to ^Kalecgos^ to advance."] = "返回 ^Wyrmrest Summit^ 後，與 ^Kalecgos^ 交談以繼續前進。",
    ["After arriving in ^Crown of Gorgoa^, follow the path North to ^Guardian of the First Ones^."] = "到達 ^Crown of Gorgoa^ 後，沿著路徑向北到達 ^Guardian of the First Ones^。",
    ["After arriving in ^The Burning Throne^, proceed down the long path and kill ^Tarneth^ to open the door. Continue west to the map exit labeled ^The World Soul^."] = "到達^The Burning Throne^後，沿著長路前進並殺死^Tarneth^以開啟門。繼續向西到達標記為 ^The World Soul^ 的地圖出口。",
    ["After arriving in ^The Burning Throne^, proceed down the path and kill ^Tarneth^ to open the door. Jump in the hole behind the next trash pack."] = "到達^The Burning Throne^後，沿著路徑前進並殺死^Tarneth^以開啟門。跳進下一個小怪堆後面的洞裡。",
    ["After arriving in ^The Emerald Nightmare^, proceed forward to start the encounter with ^Dragons of Nightmare^."] = "到達^The Emerald Nightmare^後，繼續前進，開始與^Dragons of Nightmare^的戰鬥。",
    ["After arriving in ^The Oblivion Door^, clear all trash to start the encounter with ^Zul, Reborn^."] = "到達^The Oblivion Door^後，清除所有小怪以開始與^Zul, Reborn^的戰鬥。",
    ["After arriving in ^The Twisting Nether^, work your way down the path, killing trash all the way until you reach ^Kil'jaeden^."] = "到達 ^The Twisting Nether^ 後，沿路向下前進，一路清理小怪，直到抵達 ^Kil'jaeden^。",
    ["After arriving in the room with ^Lady Inerva Darkvein^, kill all the trash to trigger some dialog, then kill the boss."] = "帶著^Lady Inerva Darkvein^到達房間後，殺死所有小怪以觸發一些對話，然後殺死首領。",
    ["After arriving on ^Wyrmrest Summit^, talk to ^Kalecgos^ to advance."] = "到達 ^Wyrmrest Summit^ 後，與 ^Kalecgos^ 交談即可前進。",
    ["After back in the ^Ring of Containment^, head to the leftmost map exit labeled ^Archives of Eternity^."] = "回到 ^Ring of Containment^ 後，前往最左邊的地圖出口，標記為 ^Archives of Eternity^。",
    ["After clearing the final trash wave, follow the path up to engage ^The Spirit Kings^."] = "清除最後一波小怪後，沿著路徑向上攻擊^The Spirit Kings^。",
    ["After clicking the ^Hammer^, proceed down the stairs towards the west side of the room and the map exit labeled ^The Abyssal Throne^."] = "點擊 ^Hammer^ 後，沿著樓梯朝房間西側和標記為 ^The Abyssal Throne^ 的地圖出口走去。",
    ["After clicking the ^Tears of Elune^, jump off the edge to die and respawn back in ^Chamber of the Moon^."] = "點擊 ^Tears of Elune^ 後，跳下邊緣死亡並在 ^Chamber of the Moon^ 中重生。",
    ["After clicking the ^Tidestone^, backtrack a bit and take a right towards the map exit labeled ^Terrace of the Moon^. You will pass a giant statue and begin climbing a long, winding staircase."] = "點擊 ^Tidestone^ 後，原路返回並向右轉至標記為 ^Terrace of the Moon^ 的地圖出口。您將經過一座巨大的雕像，並開始攀登長長的蜿蜒樓梯。",
    ["After clicking the first orb, follow the path all the way north to kill ^Radiance of Azshara^. Clear all the trash to start the encounter."] = "點擊第一個球後，沿著小路一路向北殺死^Radiance of Azshara^。清除所有小怪以開始戰鬥。",
    ["After clicking the lever, travel through the opened door to the northeast and follow it around to a big clearing. Take the southwestern door."] = "點擊控制桿後，穿過開啟的門向東北方向走，然後沿著它走到一大片空地。走西南門。",
    ["After clicking the orb, the path opens to fight ^Lady Ashvane^."] = "點擊球體後，將開啟與 ^Lady Ashvane^ 戰鬥的路徑。",
    ["After coming out of the water, take the path south towards the map exit labeled ^Darkest Depths^."] = "從水中出來後，沿著向南的路徑前往標記為 ^Darkest Depths^ 的地圖出口。",
    ["After completing the ^Hellfire Assault^ encounter, you will find ^Iron Reaver^ spawned right in front of you."] = "完成 ^Hellfire Assault^ 戰鬥後，你會發現 ^Iron Reaver^ 就在你面前出現。",
    ["After completing the ^Norushen^ encounter, move ahead into the next room and clear all trash to start the fight with ^Sha of Pride^."] = "完成 ^Norushen^ 戰鬥後，前進到下一個房間並清除所有小怪，開始與 ^Sha of Pride^ 戰鬥。",
    ["After completing the ^Spoils of Pandaria^ encounter, follow the path ahead to reach ^Thok the Bloodthirsty^."] = "完成^Spoils of Pandaria^戰鬥後，沿著前面的路徑到達^Thok the Bloodthirsty^。",
    ["After defeating ^Aggramar^, speak to ^Magni Bronzebeard^ and tell him you're ready."] = "擊敗 ^Aggramar^ 後，與 ^Magni Bronzebeard^ 交談並告訴他你已經準備好了。",
    ["After defeating ^Al'ar^, take the northwest exit and follow the path to ^Void Reaver^."] = "擊敗 ^Al'ar^ 後，從西北出口離開，沿路前往 ^Void Reaver^。",
    ["After defeating ^Aluriel^, take the path into the building to the northeast, and clear trash as you approach the map exit labeled ^Astromancer's Rise^."] = "擊敗 ^Aluriel^ 後，沿路徑進入東北部的建築物，並在接近標記為 ^Astromancer's Rise^ 的地圖出口時清除小怪。",
    ["After defeating ^Alysrazor^, you will find ^Shannox^ patrolling around the main circular path of the instance. If he hasn't spawned yet, kill random trash until he emotes."] = "擊敗^Alysrazor^後，你會發現^Shannox^在實例的主圓形路徑周圍巡邏。如果他還沒有出現，就隨機殺死小怪，直到他表現出來。",
    ["After defeating ^Amber-Shaper Un'sok^, exit the room to the west and head straight for ^Grand Empress Shek'zeer^. Clear all the trash to spawn the boss."] = "擊敗^Amber-Shaper Un'sok^後，從西邊退出房間，直奔^Grand Empress Shek'zeer^。清除所有小怪以出現 首領。",
    ["After defeating ^Anub'Rekhan^, backtrack out of his room and take a left. Stay to the left while following the path to ^Grand Widow Faerlina^."] = "擊敗 ^Anub'Rekhan^ 後，原路離開他的房間並左轉。沿路保持靠左，前往 ^Grand Widow Faerlina^。",
    ["After defeating ^Archavon^, backtrack south and take your first left to find ^Toravon the Ice Watcher^."] = "擊敗^Archavon^後，向南原路返回，在第一個路口左轉即可找到^Toravon the Ice Watcher^。",
    ["After defeating ^Argaloth^, head to the north wing to face ^Alizabal^."] = "擊敗^Argaloth^後，前往北翼面對^Alizabal^。",
    ["After defeating ^Artificer Xy'mox^, backtrack out of the room and follow the path to the stairs leading to ^Feast of Arrogance^."] = "擊敗^Artificer Xy'mox^後，原路退出房間，沿著路徑到達通往^Feast of Arrogance^的樓梯。",
    ["After defeating ^Azgalor^, take another long road to the far east. Stop and talk to ^Tyrande Whisperwind^ and continue north to ^Archimonde^."] = "擊敗 ^Azgalor^ 後，沿另一條長路一路往最東邊走。停下來與 ^Tyrande Whisperwind^ 交談，然後繼續往北前往 ^Archimonde^。",
    ["After defeating ^Baron Geddon^, continue east until you reach ^Sulfuron Harbinger^."] = "擊敗^Baron Geddon^後, 繼續向東前進，直到抵達^Sulfuron Harbinger^.",
    ["After defeating ^Beth'tilac^, follow the path all the way to the southeastern corner of the map to reach ^Lord Rhyolith^. Kill trash on your path, to minimize the amount you have to kill later to spawn ^Shannox^."] = "擊敗^Beth'tilac^後，沿著小路一直走到地圖的東南角即可到達^Lord Rhyolith^。殺死路徑上的小怪，以最大程度地減少稍後出現 ^Shannox^ 所需殺死的小怪數量。",
    ["After defeating ^Blood Prince Council^, take the ramp up and out of this room."] = "擊敗^Blood Prince Council^後，沿坡道上行並離開這個房間。",
    ["After defeating ^Brackenspore^, go back out the way you came and travel far west to reach a portal."] = "擊敗 ^Brackenspore^ 後，按原路返回，向西行駛很遠到達傳送門。",
    ["After defeating ^Buru the Gorger^, travel south up the ramp and loop around to the left to find ^Ayamiss the Hunter^."] = "擊敗^Buru the Gorger^後，沿斜坡向南上行，再繞到左側找到^Ayamiss the Hunter^。",
    ["After defeating ^Champion of the Light^, continue down the path, clearing trash on the way to ^Grong^."] = "擊敗 ^Champion of the Light^ 後，繼續沿著路徑前進，清除前往 ^Grong^ 途中的小怪。",
    ["After defeating ^Chimaeron^, go back out to the main ring and follow the path to the ^Orb of Culmination^. Interact with it to begin the encounter with ^Nefarian^."] = "擊敗 ^Chimaeron^ 後，返回主環並沿著路徑前往 ^Orb of Culmination^。與其交互以開始與 ^Nefarian^ 的戰鬥。",
    ["After defeating ^Cho'gall^, jump in the hole in the middle of the room."] = "擊敗^Cho'gall^後，跳進房間中間的洞裡。",
    ["After defeating ^Conclave of the Chosen^, exit the room to the east, and take the elevator up."] = "擊敗^Conclave of the Chosen^後，從東邊退出房間，乘電梯上去。",
    ["After defeating ^Conclave of Wind^, collect the loot chest on the north platform, then click on the nearby ^Slipstream^ to be flown to the main platform to face ^Al'Akir^."] = "擊敗^Conclave of Wind^後，在北平台收集戰利品箱，然後點擊附近的^Slipstream^飛到主平台面對^Al'Akir^。",
    ["After defeating ^Conclave^, exit the room to the east and ride the elevator up to the ^Walk of Kings^."] = "擊敗^Conclave^後，從東邊退出房間並乘坐電梯到達^Walk of Kings^。",
    ["After defeating ^Council of Elders^, go through the door behind them. As you cross the bridge, there will be a cutscene and you will fall below."] = "擊敗^Council of Elders^後，穿過他們身後的門。當你過橋時，會有一個過場動畫，你會掉到下面。",
    ["After defeating ^Dark Animus^, take the northern stairwell out of the room and follow the path to open a masked gate."] = "擊敗^Dark Animus^後，從北邊的樓梯間走出房間，沿著路徑開啟一扇蒙面門。",
    ["After defeating ^Durumu^, follow the linear path through several sets of stairs and make your way to ^Primordius^."] = "擊敗 ^Durumu^ 後，沿著直線路徑穿過幾組樓梯，前往 ^Primordius^。",
    ["After defeating ^Ebonroc^, go up the ramp behind him."] = "擊敗^Ebonroc^後，從他身後的斜坡上去。",
    ["After defeating ^Echo of Neltharion^, walk into the room behind him and jump into the purple circle to reach ^Edge of Oblivion^."] = "擊敗^Echo of Neltharion^後，走進他身後的房間，跳入紫色圓圈到達^Edge of Oblivion^。",
    ["After defeating ^Elerethe^, backtrack to the portal and return to ^Core of the Nightmare^. You can jump off the ledge for a shortcut."] = "擊敗^Elerethe^後，原路返回傳送門並返回^Core of the Nightmare^。你可以從壁架上跳下來走捷徑。",
    ["After defeating ^Elisande^, approach the teleporter outside the room and choose ^Font of Night^ as your destination."] = "擊敗^Elisande^後，接近房間外的傳送器並選擇^Font of Night^作為目的地。",
    ["After defeating ^Eredar Twins^, exit northwest and follow the path to the spiral ramp. Continue on the path until you reach ^M'uru^."] = "擊敗 ^Eredar Twins^ 後，從西北方向離開，沿路前往螺旋斜坡。繼續沿路前進，直到抵達 ^M'uru^。",
    ["After defeating ^Faerlina^, head southeast and follow the path back north all the way to ^Maexxna^."] = "擊敗 ^Faerlina^ 後，向東南前進，再沿路一路向北前往 ^Maexxna^。",
    ["After defeating ^Fathom-Lord Karathress^, take the eastern path out of the room and follow the path to ^Morogrim Tidewalker^."] = "擊敗 ^Fathom-Lord Karathress^ 後，從房間東側路線離開，沿路前往 ^Morogrim Tidewalker^。",
    ["After defeating ^Fel Lord Zakuun^, climb out of this area the way you came, and go all the way east to reach ^Xhul'horac^. Kill trash to start the encounter."] = "擊敗^Fel Lord Zakuun^後，按來時的路爬出該區域，一路向東到達^Xhul'horac^。殺死小怪來開始戰鬥。",
    ["After defeating ^Felhounds of Sargeras^, backtrack towards the closest intersection and keep to the left. Kill a trash pack to spawn a ^Lightforged Teleportation Pad^. Use it to cross the chasm, then proceed ahead to ride an elevator up."] = "擊敗 ^Felhounds of Sargeras^ 後，原路返回最近的十字路口並保持左側行駛。殺死小怪群以出現 ^Lightforged Teleportation Pad^。用它穿過峽谷，然後繼續乘坐電梯上去。",
    ["After defeating ^Festergut^, click the ^Gas Release Valve^ on the left side of the exit door. Then follow the path around to ^Rotface^."] = "擊敗^Festergut^後，點擊出口門左側的^Gas Release Valve^，然後沿路前往^Rotface^。",
    ["After defeating ^Firemaw^, continue northwest until you reach ^Ebonroc^."] = "擊敗^Firemaw^後, 繼續向西北前進，直到抵達^Ebonroc^.",
    ["After defeating ^Flame Leviathan^, proceed forward and take your first left. Follow the path down to ^Ignis the Furnace Master^."] = "擊敗^Flame Leviathan^後，向前走並在第一個路口左轉。沿路下行前往^Ignis the Furnace Master^。",
    ["After defeating ^Flamebender Ka'graz^, head slightly east and then follow the path north to reach ^Kromog^."] = "擊敗^Flamebender Ka'graz^後，稍微向東走，然後沿著路徑向北到達^Kromog^。",
    ["After defeating ^Freya^, backtrack to the ring and take the path northwest towards the map exit labeled ^The Spark of Imagination^. Climb aboard the tram and click the console to ^Activate Tram^."] = "擊敗^Freya^後，返回環形區域，沿西北方向前往地圖出口^The Spark of Imagination^。登上軌道車並點擊控制台^Activate Tram^。",
    ["After defeating ^Garothi Worldbreaker^, continue straight ahead on the path to ^Felhounds of Sargeras^."] = "擊敗^Garothi Worldbreaker^後，繼續沿著通往^Felhounds of Sargeras^的道路前進。",
    ["After defeating ^Garothi Worldbreaker^, cross the bridge and take a left to locate a teleporter. Select ^The Burning Throne^ to skip ahead to ^Aggramar^."] = "擊敗^Garothi Worldbreaker^後，過橋並向左轉找到傳送器。選擇 ^The Burning Throne^ 以跳至 ^Aggramar^。",
    ["After defeating ^Gehennas^, continue south to ^Garr^."] = "擊敗^Gehennas^後, 繼續向南前進，直到抵達^Garr^.",
    ["After defeating ^General Nazgrim^, take the elevator down in the northeastern section of the room."] = "擊敗^General Nazgrim^後，乘坐房間東北部的電梯下去。",
    ["After defeating ^General Rajaxx^, travel northwest until you reach ^Moam^."] = "擊敗^General Rajaxx^後, 向西北前進，直到抵達^Moam^.",
    ["After defeating ^General Vezax^, continue behind him to reach ^Yogg-Saron^. Approach ^Sara^ to start the encounter. See special note for |cffF259C7Hard Mode|r."] = "擊敗^General Vezax^後，從他身後繼續前進即可到達^Yogg-Saron^。靠近^Sara^以開始戰鬥。請查看|cffF259C7困難模式|r特別提示。",
    ["After defeating ^Goroth^, proceed straight ahead past the group of NPCs and go up the stairs to find ^Demonic Inquisition^."] = "擊敗 ^Goroth^ 後，繼續直行，經過一群 NPC 並上樓，找到 ^Demonic Inquisition^。",
    ["After defeating ^Gothik the Harvester^, take the south exit and follow the path around to reach ^The Four Horsemen^."] = "擊敗 ^Gothik the Harvester^ 後，從南出口離開並沿路前往 ^The Four Horsemen^。",
    ["After defeating ^Grobbulus^, exit south from the top of the room. Walk across a pipe as you follow the path around to find ^Gluth^."] = "擊敗 ^Grobbulus^ 後，從房間上層的南側出口離開。沿路走過一根管道，前往 ^Gluth^。",
    ["After defeating ^Grong^, follow the winding path around to ^Jadefire Masters^. Kill the trash to start the encounter."] = "擊敗^Grong^後，沿著蜿蜒的小路前往^Jadefire Masters^。殺死小怪來開始戰鬥。",
    ["After defeating ^Hagara^, click the ^portal^ to return to ^Wyrmrest Summit^."] = "擊敗^Hagara^後，點擊^portal^返回^Wyrmrest Summit^。",
    ["After defeating ^Halfus^, follow the path straight south to reach ^Theralion and Valiona^. Kill trash to begin the gauntlet on the way to the boss."] = "擊敗^Halfus^後，沿著小路一直向南到達^Theralion and Valiona^。殺死小怪，在通往 首領 的路上開始挑戰。",
    ["After defeating ^Heigan^, exit to the east and follow the path around to ^Loatheb^."] = "擊敗 ^Heigan^ 後，從東側出口離開並沿路前往 ^Loatheb^。",
    ["After defeating ^High Botanist Tel'arn^, backtrack towards the map exit labeled ^The Nighthold^."] = "擊敗 ^High Botanist Tel'arn^ 後，原路返回標記為 ^The Nighthold^ 的地圖出口。",
    ["After defeating ^High King Maulgar^, continue up the path to ^Gruul the Dragonkiller^."] = "擊敗 ^High King Maulgar^ 後，繼續沿路往上前往 ^Gruul the Dragonkiller^。",
    ["After defeating ^High Warlord Naj'entus^, make your way up and through a pipe on the west side of the room."] = "擊敗 ^High Warlord Naj'entus^ 後，往上走並穿過房間西側的管道。",
    ["After defeating ^Hodir^, return to the ring and take the northeast path towards ^Thorim^. Kill the trash to start the fight. See special note for |cffF259C7Hard Mode|r."] = "擊敗^Hodir^後，返回環形區域並沿東北方向前往^Thorim^。清理敵人以開始戰鬥。請查看|cffF259C7困難模式|r特別提示。",
    ["After defeating ^Hydross the Unstable^, head north and jump down to the platform in the middle of the water. Cast ^Fishing^ in the water swirl until you fish up ^The Lurker Below^."] = "擊敗 ^Hydross the Unstable^ 後，往北走並跳到水中央的平台。對水中的漩渦使用 ^Fishing^，直到釣起 ^The Lurker Below^。",
    ["After defeating ^Il'gynoth^, interact with the nearby ^Re-origination Anchor^ to be flown back to the top."] = "擊敗^Il'gynoth^後，與附近的^Re-origination Anchor^互動即可飛回頂部。",
    ["After defeating ^Immerseus^, take the tall western stairwell behind him."] = "擊敗^Immerseus^後，走他身後高高的西樓梯井。",
    ["After defeating ^Iron Maidens^, take the southern path and keep to the left until you reach ^Hans'gar and Franzok^. After a brief dialog, kill the trash to start the encounter."] = "擊敗^Iron Maidens^後，走南邊的道路並保持向左行駛，直到到達^Hans'gar and Franzok^。簡短的對話後，殺死小怪即可開始戰鬥。",
    ["After defeating ^Iron Qon^, proceed through the new door behind them and follow the linear path to the ^Twin Empyreans^."] = "擊敗^Iron Qon^後，穿過他們身後的新門，沿著線性路徑到達^Twin Empyreans^。",
    ["After defeating ^Jadefire Masters^, go up the stairs behind them toward the map exit labeled ^The Heart of the Empire^. Open the door to continue."] = "擊敗 ^Jadefire Masters^ 後，上他們身後的樓梯，前往標記為 ^The Heart of the Empire^ 的地圖出口。開啟門繼續。",
    ["After defeating ^Jadefire Masters^, proceed up the long staircase behind them to reach ^Grong, the Revenant^. Kill trash at the top of the stairs to start the encounter."] = "擊敗^Jadefire Masters^後，沿著他們身後的長樓梯前進到達^Grong, the Revenant^。殺死樓梯頂部的小怪即可開始戰鬥。",
    ["After defeating ^Kalecgos^, continue east and follow the path towards ^Brutallus^."] = "擊敗 ^Kalecgos^ 後，繼續往東並沿路前往 ^Brutallus^。",
    ["After defeating ^Kazzara^, click the vent behind ^Neltharion^ and you will be able to jump down and skip ahead to the ^Echo of Neltharion^ encounter."] = "擊敗^Kazzara^後，點擊^Neltharion^後面的通風口，你將能夠跳下來並向前跳到^Echo of Neltharion^戰鬥。",
    ["After defeating ^King Rastakhan^, take the western exit from the room and make your way towards the map exit labeled ^Port of Zandalar^. Interact with the ^7th Legion Gryphon^ to be flown to the next area."] = "擊敗 ^King Rastakhan^ 後，從房間的西出口前往標記為 ^Port of Zandalar^ 的地圖出口。與 ^7th Legion Gryphon^ 互動以飛往下一個區域。",
    ["After defeating ^King Rastakhan^, take the western exit from the room and make your way towards the map exit labeled ^Port of Zandalar^. Interact with the ^Riding Pterrordax^ to be flown to the next area."] = "擊敗 ^King Rastakhan^ 後，從房間的西面出口前往標記為 ^Port of Zandalar^ 的地圖出口。與 ^Riding Pterrordax^ 互動以飛往下一個區域。",
    ["After defeating ^Kologarn^, cross his bridge-like body and go down the stairs to reach ^The Inner Sanctum of Ulduar^."] = "擊敗^Kologarn^後，從他如同橋梁的身體上走過，再下樓前往^The Inner Sanctum of Ulduar^。",
    ["After defeating ^Koralon^, backtrack and head north all the way to ^Archavon the Stone Watcher^."] = "擊敗^Koralon^後，原路返回並一路向北前往^Archavon the Stone Watcher^。",
    ["After defeating ^Krosus^, backtrack up to the main courtyard and click the portal to teleport to ^The Nightspire^. After landing, proceed ahead into the boss room."] = "擊敗^Krosus^後，原路返回主庭院，點擊傳送門傳送至^The Nightspire^。落地後，繼續前進，進入首領房間。",
    ["After defeating ^Kurinnaxx^, continue south until you reach ^General Rajaxx^."] = "擊敗^Kurinnaxx^後, 繼續向南前進，直到抵達^General Rajaxx^.",
    ["After defeating ^Lady Deathwhisper^, an elevator will drop down. Ride this elevator up to the next area."] = "擊敗^Lady Deathwhisper^後，電梯會降下。乘坐電梯前往下一個區域。",
    ["After defeating ^Lei Shi^, continue straight up the stairs to engage ^Sha of Fear^."] = "擊敗^Lei Shi^後，繼續直接上樓梯與^Sha of Fear^交戰。",
    ["After defeating ^Lord Jaraxxus^, talk to ^Barrett Ramsey^ again to start the next encounter vs. ^Champions of the Horde^."] = "擊敗^Lord Jaraxxus^後，再次與^Barrett Ramsey^交談，開始下一場對陣^Champions of the Horde^的戰鬥。",
    ["After defeating ^Magmadar^, follow the path west until you reach ^Gehennas^."] = "擊敗^Magmadar^後, 沿路向西前進，直到抵達^Gehennas^.",
    ["After defeating ^Magmorax^, swim across the lava to reach the southern exit labeled ^Neltharion's Sanctum^. Jump down into the hole."] = "擊敗 ^Magmorax^ 後，游過熔岩到達標有 ^Neltharion's Sanctum^ 的南部出口。跳進洞裡。",
    ["After defeating ^Maiden of Virtue^, follow the long, winding path until you reach ^Barnes^. Talk to him to start the ^Opera Hall^ encounter."] = "擊敗 ^Maiden of Virtue^ 後，沿著漫長蜿蜒的路線前進，直到抵達 ^Barnes^。與他交談以開始 ^Opera Hall^ 戰鬥。",
    ["After defeating ^Majordomo Executus^, jump down and make your way to the center of the instance. Talk to ^Majordomo^ to summon ^Ragnaros^."] = "擊敗^Majordomo Executus^後，跳下去前往副本中央。與^Majordomo^交談以召喚^Ragnaros^。",
    ["After defeating ^Maloriak^, exit back to the main ring and head to the north exit. Kill trash, then hit the large bell at the back of the room to begin the encounter with ^Atramedes^."] = "擊敗^Maloriak^後，返回主環並前往北出口。殺死小怪，然後敲響房間後面的大鈴，開始與 ^Atramedes^ 的戰鬥。",
    ["After defeating ^Megaera^, take the new exit on the east side of the room."] = "擊敗^Megaera^後，從房間東側的新出口走。",
    ["After defeating ^Mekkatorque^, make your way down the long path south, and kill the trash at the end of the bridge. Interact with a ^Pterrordax^ to start the encounter with ^Stormwall Blockade^."] = "擊敗^Mekkatorque^後，沿著長長的小路向南走，殺死橋盡頭的小怪。與 ^Pterrordax^ 交互以開始與 ^Stormwall Blockade^ 的戰鬥。",
    ["After defeating ^Morchok^, continue ahead into ^Wyrmrest Temple^. Interact with ^Valeera^, the dragon on the left."] = "擊敗^Morchok^後，繼續前進進入^Wyrmrest Temple^。與左邊的龍^Valeera^互動。",
    ["After defeating ^Morogrim Tidewalker^, continue south, and work your way around the path to the east until you reach the ^Lady Vashj Bridge Console^. Click the console to open the bridge, then cross it to reach the final boss, ^Lady Vashj^."] = "擊敗 ^Morogrim Tidewalker^ 後，繼續往南，再沿路線繞往東邊，直到抵達 ^Lady Vashj Bridge Console^。點擊控制台打開橋樑，然後過橋前往最終首領 ^Lady Vashj^。",
    ["After defeating ^Mother Shahraz^, take the nearby exit to the south."] = "擊敗 ^Mother Shahraz^ 後，從附近的南側出口離開。",
    ["After defeating ^MOTHER^, continue forward to the map exit labeled ^Ring of Containment^."] = "擊敗^MOTHER^後，繼續前往標記為^Ring of Containment^的地圖出口。",
    ["After defeating ^Mythrax^, follow the path north to engage the final boss, ^G'huun^."] = "擊敗 ^Mythrax^ 後，沿著北邊的道路與最終 首領 ^G'huun^ 交戰。",
    ["After defeating ^Nightbane^, exit to the east (the way you came in). Back in ^The Broken Stair^, go up the ramp right above you and take a right when you reach the top."] = "擊敗 ^Nightbane^ 後，往東離開（沿來時的路）。回到 ^The Broken Stair^ 後，沿你正上方的斜坡上去，到頂端後右轉。",
    ["After defeating ^Noth^, exit to the east and follow the path around to ^Heigan the Unclean^."] = "擊敗 ^Noth^ 後，從東側出口離開並沿路前往 ^Heigan the Unclean^。",
    ["After defeating ^Nythendra^, follow the path up and around towards the map exit labeled ^Core of the Nightmare^."] = "擊敗 ^Nythendra^ 後，沿著路徑向上並繞過標記為 ^Core of the Nightmare^ 的地圖出口。",
    ["After defeating ^Odyn^, talk to him and select the only dialog option available. You will be dropped into ^Helheim^."] = "擊敗 ^Odyn^ 後，與他交談並選擇唯一可用的對話選項。您將被放入 ^Helheim^。",
    ["After defeating ^Opera Hall^, go up the ramp on the south side of the stage."] = "擊敗 ^Opera Hall^ 後，從舞台南側的斜坡上去。",
    ["After defeating ^Operator Thogar^, jump down the hole marked on the east side of the room."] = "擊敗^Operator Thogar^後，跳下房間東側標記的洞。",
    ["After defeating ^Ouro^, travel northwest and stay to the right as you work your way up a long spiral."] = "擊敗^Ouro^後，向西北前進，沿著長螺旋上行時靠右。",
    ["After defeating ^Portal Keeper Hasabel^, leave the boss room and stay to the right to find the map exit labeled ^Elunaria^. Click the portal."] = "擊敗^Portal Keeper Hasabel^後，離開首領房間並留在右側找到標記為^Elunaria^的地圖出口。點擊傳送門。",
    ["After defeating ^Professor Putricide^, backtrack to the main ring and take the northern path to reach ^Blood Prince Council^."] = "擊敗^Professor Putricide^後，返回主環形區域並沿北側通道前往^Blood Prince Council^。",
    ["After defeating ^Protectors of the Endless^, there will be a brief delay and then ^Tsulong^ will spawn at the same location."] = "擊敗 ^Protectors of the Endless^ 後，會有短暫的延遲，然後 ^Tsulong^ 將在同一位置出現。",
    ["After defeating ^Ra-den^, interact with the ^Re-origination Anchor^ right behind him to be flown back below."] = "擊敗^Ra-den^後，與他身後的^Re-origination Anchor^互動，使其飛回下方。",
    ["After defeating ^Radiance of Azshara^, leave the room the way you came and find 2 more ^Azsh'ari Channelers^ guarding an orb. Kill them and click ^Font of Power^."] = "擊敗 ^Radiance of Azshara^ 後，按來時的路離開房間，發現另外 2 個 ^Azsh'ari Channelers^ 守衛著一個球體。殺死他們並點擊 ^Font of Power^。",
    ["After defeating ^Rage Winterchill^, speak to ^Lady Jaina Proudmoore^ to begin the next encounter against ^Anetheron^."] = "擊敗 ^Rage Winterchill^ 後，與 ^Lady Jaina Proudmoore^ 交談，開始下一場與 ^Anetheron^ 的戰鬥。",
    ["After defeating ^Rashok^, make your way up the chain behind him, and follow the path around to ^The Vigilant Steward, Zskarn^."] = "擊敗 ^Rashok^ 後，沿著他身後的鏈條向上走，然後沿著周圍的路徑到達 ^The Vigilant Steward, Zskarn^。",
    ["After defeating ^Razorgore^, proceed northwest into the next room. Talk to ^Vaelastrasz the Corrupt^ to start the encounter."] = "擊敗^Razorgore^後，向西北進入下一個房間。與^Vaelastrasz the Corrupt^交談開始戰鬥。",
    ["After defeating ^Razuvious^, take the south exit and follow the path around to reach ^Gothik the Harvester^. Tag him to start the encounter."] = "擊敗 ^Razuvious^ 後，從南出口離開並沿路前往 ^Gothik the Harvester^。攻擊他以開始戰鬥。",
    ["After defeating ^Reliquary of Souls^, backtrack to the main concourse."] = "擊敗 ^Reliquary of Souls^ 後，原路返回主大廳。",
    ["After defeating ^Sha of Pride^, watch some dialog then click the portal in the southwest corner of the room."] = "擊敗^Sha of Pride^後，觀看一些對話，然後點擊房間西南角的傳送門。",
    ["After defeating ^Shad'har^, leave his room and continue down the spiral."] = "擊敗^Shad'har^後，離開他的房間並繼續沿著螺旋向下走。",
    ["After defeating ^Shade of Akama^, backtrack out of this room and go east towards ^Gorefiend's Vigil^. Follow the path up a couple sets of stairs."] = "擊敗 ^Shade of Akama^ 後，從這個房間原路返回，並往東前往 ^Gorefiend's Vigil^。沿路往上，經過幾段樓梯。",
    ["After defeating ^Shade of Aran^, exit the library and take a left up the ramp."] = "擊敗 ^Shade of Aran^ 後，離開圖書館並左轉上坡。",
    ["After defeating ^Shannox^, head north to reach ^Baleroc^."] = "擊敗^Shannox^後，向北前往^Baleroc^。",
    ["After defeating ^Siegecrafter Blackfuse^, jump back in the pipe towards the room entrance. Continue southwest back the way you came."] = "擊敗 ^Siegecrafter Blackfuse^ 後，跳回管道中進入房間入口。繼續向西南方向返回。",
    ["After defeating ^Silithid Royalty^, backtrack out of their room. Go slightly up the ramp and exit north to find your way to ^Battleguard Sartura^."] = "擊敗^Silithid Royalty^後，原路離開房間。沿斜坡稍微上行，從北側出去前往^Battleguard Sartura^。",
    ["After defeating ^Sisters of the Moon^, leave the boss room and take a left. Follow the winding path back to ^The Desolate Host^."] = "擊敗^Sisters of the Moon^後，離開首領房間並向左走。沿著蜿蜒的小路回到^The Desolate Host^。",
    ["After defeating ^Sivara^, continue past her towards the map exit labeled ^Halls of the Chosen^. Take the underwater tunnel to reach the next area."] = "擊敗 ^Sivara^ 後，繼續經過她，前往標記為 ^Halls of the Chosen^ 的地圖出口。沿著水下隧道到達下一個區域。",
    ["After defeating ^Skolex^, follow the ring path up and around to ^Artificer Xy'mox^."] = "擊敗 ^Skolex^ 後，沿著環形路徑向上繞行至 ^Artificer Xy'mox^。",
    ["After defeating ^Skorpyron^, take the new southeast exit up the ramp and make your way towards ^Chronomatic Anomaly^. Kill trash on the way to open the door."] = "擊敗 ^Skorpyron^ 後，從新的東南出口走上坡道，前往 ^Chronomatic Anomaly^。在開門的路上殺掉小怪。",
    ["After defeating ^Socrethar the Eternal^, leave the room to the south. In the next room, click 4x ^Demon Portals^ then kill ^Lord Aram'el^ to open the door. Proceed along the path to ^Tyrant Velhari^."] = "擊敗^Socrethar the Eternal^後，離開南邊的房間。在下一個房間，點擊 4x ^Demon Portals^ 然後殺 ^Lord Aram'el^ 開啟門。沿著路徑前往 ^Tyrant Velhari^。",
    ["After defeating ^Star Augur Etraeus^, backtrack down the stairs to return to ^Astromancer's Rise^."] = "擊敗^Star Augur Etraeus^後，原路下樓梯返回^Astromancer's Rise^。",
    ["After defeating ^Stormwall Blockade^, walk onto the newly-arrived ship and speak with ^Captain Zadari^ to begin the ^Lady Jaina Proudmoore^ encounter."] = "擊敗^Stormwall Blockade^後，走上新抵達的船隻並與^Captain Zadari^交談以開始^Lady Jaina Proudmoore^戰鬥。",
    ["After defeating ^Sun King's Salvation^, go back the way you came and return down the stairs to ^Halls of the Faithful^."] = "擊敗^Sun King's Salvation^後，原路返回，下樓梯回到^Halls of the Faithful^。",
    ["After defeating ^Supremus^, continue up the ramp behind him into the next area."] = "擊敗 ^Supremus^ 後，沿他身後的斜坡上去進入下一區域。",
    ["After defeating ^Tectus^, follow the path northeast to reach ^Brackenspore^."] = "擊敗^Tectus^後，沿著東北方向到達^Brackenspore^。",
    ["After defeating ^Tectus^, leave his area and take a left to reach a portal."] = "擊敗 ^Tectus^ 後，離開他的區域並向左轉到達傳送門。",
    ["After defeating ^Terestian Illhoof^, backtrack up the ramp and back through the bookcase."] = "擊敗 ^Terestian Illhoof^ 後，沿斜坡原路返回，再次穿過書架。",
    ["After defeating ^Thaddius^, click the ^Naxxramas Portal^."] = "擊敗 ^Thaddius^ 後，點擊 ^Naxxramas Portal^。",
    ["After defeating ^The Assembly of Iron^, backtrack to ^The Antechamber^ and go up the stairs to reach ^Kologarn^."] = "擊敗^The Assembly of Iron^後，返回^The Antechamber^並上樓前往^Kologarn^。",
    ["After defeating ^The Blast Furnace^, go straight ahead back up the spiral ramp. When you reach the bridge area, take a right and go up another ramp towards the main lobby."] = "擊敗 ^The Blast Furnace^ 後，徑直返回螺旋坡道。當您到達橋區時，右轉並沿另一個坡道前往主大廳。",
    ["After defeating ^The Butcher^, take the western exit out of his area and follow the path north to ^Brackenspore^."] = "擊敗 ^The Butcher^ 後，從西邊出口離開他的區域，然後沿著路向北到達 ^Brackenspore^。",
    ["After defeating ^The Coven of Shivarra^, take some stairs out of the area and make your way west towards the map exit labeled ^The World Soul^."] = "擊敗 ^The Coven of Shivarra^ 後，走一些樓梯離開該區域，並向西朝標記為 ^The World Soul^ 的地圖出口走。",
    ["After defeating ^The Demonic Inquisition^, follow the path to ^Terrace of the Moon^."] = "擊敗^The Demonic Inquisition^後，沿著路徑前往^Terrace of the Moon^。",
    ["After defeating ^The Fallen Protectors^, follow the path to the mineshaft. Kill ^Zeal^ to unlock the way."] = "擊敗^The Fallen Protectors^後，沿著路徑前往礦井。殺死^Zeal^即可解鎖道路。",
    ["After defeating ^The Forgotten Experiments^, jump down behind them (under a chain) and take the path across the room to the exit labeled ^Defiant Ramparts^."] = "擊敗 ^The Forgotten Experiments^ 後，跳到他們後面（在鏈條下），沿著路徑穿過房間到達標有 ^Defiant Ramparts^ 的出口。",
    ["After defeating ^The Four Horsemen^, click the ^Naxxramas Portal^ to be teleported back to the entrance."] = "擊敗 ^The Four Horsemen^ 後，點擊 ^Naxxramas Portal^ 傳送回入口。",
    ["After defeating ^The Northrend Beasts^, talk to ^Barrett Ramsey^ again to start the next encounter vs. ^Lord Jaraxxus^."] = "擊敗^The Northrend Beasts^後，再次與^Barrett Ramsey^交談，開始下一場對陣^Lord Jaraxxus^的戰鬥。",
    ["After defeating ^The Queen's Court^, head up some stairs towards the map exit labeled ^Precipice of Dreams^."] = "擊敗 ^The Queen's Court^ 後，上樓梯前往標記為 ^Precipice of Dreams^ 的地圖出口。",
    ["After defeating ^The Restless Cabal^, there will be a cutscene where you will fall into a deep hole, landing in ^Tendril of Corruption^. Follow the path all the way back to reach ^Uu'nat^."] = "擊敗^The Restless Cabal^後，會有一個過場動畫，你會掉進一個深洞，降落在^Tendril of Corruption^。沿著小路一路返回即可到達^Uu'nat^。",
    ["After defeating ^The Spirit Kings^, go downstairs to the previous room and take the new path by ^Lorewalker Cho^."] = "擊敗^The Spirit Kings^後，下樓到之前的房間，走^Lorewalker Cho^的新路徑。",
    ["After defeating ^The Stone Guard^, continue ahead to several trash packs with glowing orbs floating near them. Physically walk into the adds to spawn the trash. Once they're down, you can engage ^Feng the Accursed^."] = "擊敗 ^The Stone Guard^ 後，繼續前進，看到幾個小怪群，周圍漂浮著發光的球體。物理上走進小怪以產生小怪。一旦它們宕機，您就可以使用 ^Feng the Accursed^。",
    ["After defeating ^The Twin Emperors^, exit the room to the southwest and follow the path until you reach ^Ouro^. You can spawn him by walking over the patch of rumbling rocks."] = "擊敗^The Twin Emperors^後，從西南離開房間並沿路前往^Ouro^。走過震動的岩石區域即可讓他出現。",
    ["After defeating ^Thok^, backtrack all the way past ^Spoils of Pandaria^ to arrive back in ^Underhold Nexus^."] = "擊敗^Thok^後，一路原路返回^Spoils of Pandaria^，回到^Underhold Nexus^。",
    ["After defeating ^Thorim^, backtrack to the ring and take the northern path to reach ^Freya^. Note: You can mount up in here. See special note for |cffF259C7Hard Mode|r."] = "擊敗^Thorim^後，返回環形區域並沿北側通道前往^Freya^。注意：這裡可以騎乘坐騎。請查看|cffF259C7困難模式|r特別提示。",
    ["After defeating ^Toravon^, backtrack south and take the next left to reach ^Emalon the Storm Watcher^."] = "擊敗^Toravon^後，向南原路返回，在下一個路口左轉前往^Emalon the Storm Watcher^。",
    ["After defeating ^Tortos^, walk through him to reach the next area. To spawn ^Megaera^, you must destroy the (3) bells marked on the map, which are protected by ^Eternal Guardians^."] = "擊敗^Tortos^後，穿過他到達下一個區域。要出現 ^Megaera^，您必須摧毀地圖上標記的 (3) 個鐘，這些鐘受到 ^Eternal Guardians^ 的保護。",
    ["After defeating ^Trilliax^, take the northwest exit out of the room and make your way up the spiral staircase."] = "擊敗^Trilliax^後，從西北出口離開房間，然後沿著螺旋樓梯向上走。",
    ["After defeating ^Tsulong^, keep moving straight ahead and kill the trash to spawn ^Lei Shi^."] = "擊敗^Tsulong^後，繼續向前移動並殺死小怪以出現^Lei Shi^。",
    ["After defeating ^Twin Ogron^, proceed up the stairwell behind them to reach ^Ko'ragh^. Clear trash to start the encounter."] = "擊敗 ^Twin Ogron^ 後，沿著他們身後的樓梯井到達 ^Ko'ragh^。清除小怪以開始戰鬥。",
    ["After defeating ^Ultraxion^, wait for the cutscene, then board the ship and talk to ^Sky Captain Swayze^ to advance."] = "擊敗^Ultraxion^後，等待過場動畫，然後登船並與^Sky Captain Swayze^對話即可前進。",
    ["After defeating ^Vaelastrasz^, take the northwest stairwell out of the room."] = "擊敗^Vaelastrasz^後，從西北樓梯離開房間。",
    ["After defeating ^Varimathras^, take the ascending stairwell out of the room towards ^Temple of Anguish^."] = "擊敗^Varimathras^後，從房間的上升樓梯井前往^Temple of Anguish^。",
    ["After defeating ^Void Reaver^, backtrack out of the room and head north as you loop around to ^High Astromancer Solarian^."] = "擊敗 ^Void Reaver^ 後，原路離開房間並往北繞行前往 ^High Astromancer Solarian^。",
    ["After defeating ^Warlord Zon'ozz^, return to ^Wyrmrest Temple^ by clicking the ^Portal^."] = "擊敗 ^Warlord Zon'ozz^ 後，返回 ^Wyrmrest Temple^，並點擊 ^Portal^。",
    ["After defeating ^Wind Lord Mel'jarak^, take the southern stairwell and follow the linear path all the way to ^Amber-Shaper Un'sok^."] = "擊敗^Wind Lord Mel'jarak^後，走南邊的樓梯井，沿著直線路徑一直到達^Amber-Shaper Un'sok^。",
    ["After defeating ^Wrathion^, proceed through the long northern path to the map exit labeled ^Ny'alotha^. Take the elevator up, and continue through the door ahead."] = "擊敗 ^Wrathion^ 後，穿過漫長的北方道路到達標記為 ^Ny'alotha^ 的地圖出口。乘電梯上去，從前面的門繼續走。",
    ["After defeating ^Wrathion^, you can proceed up the long bridge straight to ^Carapace of N'Zoth^."] = "擊敗^Wrathion^後，您可以沿著長橋直行至^Carapace of N'Zoth^。",
    ["After defeating ^XT-002 Deconstructor^, click the ^Ulduar Teleporter^ atop the stairs. Select ^Antechamber of Ulduar^."] = "擊敗^XT-002 Deconstructor^後，點擊樓梯頂部的^Ulduar Teleporter^，選擇^Antechamber of Ulduar^。",
    ["After defeating ^Yogg-Saron^, exit the room and take the ^Ulduar Teleporter^ to ^Antechamber of Ulduar^."] = "擊敗^Yogg-Saron^後，離開房間並使用^Ulduar Teleporter^前往^Antechamber of Ulduar^。",
    ["After defeating ^Yor'sahj^, return to ^Wyrmrest Temple^ by clicking the ^Portal^."] = "擊敗 ^Yor'sahj^ 後，返回 ^Wyrmrest Temple^，並點擊 ^Portal^。",
    ["After defeating ^Zskarn^, drop down into the hole behind ^Neltharion^. Leap down again (across some lava), and make your way to the boss platform. Clear the trash to spawn ^Magmorax^."] = "擊敗^Zskarn^後，掉入^Neltharion^後面的洞裡。再次跳下（穿過一些熔岩），並前往首領平台。清除小怪以出現 ^Magmorax^。",
    ["After defeating the ^Ascendant Council^, continue down the southern path until you reach ^Cho'gall^."] = "擊敗 ^Ascendant Council^ 後，繼續沿著南邊的道路前進，直到到達 ^Cho'gall^。",
    ["After defeating the ^Assault of the Zaqali^, enter the nearby room labeled ^Molten Crucible^."] = "擊敗^Assault of the Zaqali^後，進入附近標有^Molten Crucible^的房間。",
    ["After defeating the ^Champion of the Light^, follow the linear path to the right and work your way towards the next boss, ^Jadefire Masters^. Kill the final trash pack before running up the stairs."] = "擊敗 ^Champion of the Light^ 後，沿著右側的線性路徑朝下一個 首領 ^Jadefire Masters^ 前進。在跑上樓梯之前殺死最後一個小怪群。",
    ["After defeating the ^Champions of the Horde^, talk to ^Barrett Ramsey^ again to start the next encounter vs. ^Twin Val'kyr^."] = "擊敗^Champions of the Horde^後，再次與^Barrett Ramsey^交談，開始下一場對陣^Twin Val'kyr^的戰鬥。",
    ["After defeating the ^Chess Event^, leave the room up the stairs to the northeast, and follow the path to a spiral staircase."] = "完成 ^Chess Event^ 後，從房間東北側樓梯離開，沿路前往螺旋樓梯。",
    ["After defeating the ^Dragons of Nightmare^, go back the way you came and return to ^Core of the Nightmare^."] = "擊敗^Dragons of Nightmare^後，原路返回^Core of the Nightmare^。",
    ["After defeating the ^Felhounds of Sargeras^, click the ^Lightforged Teleportation Pad^ in their boss room to be teleported further up the path. After landing, proceed ahead to ride the elevator up."] = "擊敗 ^Felhounds of Sargeras^ 後，點擊其 首領 房間中的 ^Lightforged Teleportation Pad^ 即可傳送到更遠的路徑。落地後，繼續乘坐電梯上行。",
    ["After defeating the ^Hellfire High Council^, take the southwestern exit out of the room and follow the long linear path to ^Kilrogg Deadeye^."] = "擊敗^Hellfire High Council^後，從西南出口離開房間，沿著長長的線性路徑到達^Kilrogg Deadeye^。",
    ["After defeating the ^Icecrown Gunship Battle^, exit the ship."] = "擊敗^Icecrown Gunship Battle^後，離開飛艇。",
    ["After defeating the ^Omnotron Defense System^, go back downstairs and proceed straight ahead to reach ^Magmaw^."] = "擊敗^Omnotron Defense System^後，回到樓下，繼續向前到達^Magmaw^。",
    ["After defeating the ^Paragons of the Klaxxi^, take the new exit on the south side of the room. As you approach ^Garrosh^, pull the hallway trash with you and most of the dialog will be skipped!"] = "擊敗^Paragons of the Klaxxi^後，從房間南側的新出口走。當您接近 ^Garrosh^ 時，隨身攜帶走廊小怪，大部分對話將被跳過！",
    ["After defeating the ^Spine of Deathwing^, talk to ^Thrall^ (twice) to begin the final battle with ^Madness of Deathwing^."] = "擊敗 ^Spine of Deathwing^ 後，與 ^Thrall^ 交談（兩次），開始與 ^Madness of Deathwing^ 的最終戰鬥。",
    ["After defeating the ^Twin Val'kyr^, talk to ^Barrett Ramsey^ again to start the final encounter vs. ^Anub'arak^."] = "擊敗^Twin Val'kyr^後，再次與^Barrett Ramsey^交談，開始最終的^Anub'arak^戰鬥。",
    ["After defeating the ^Valithria Dreamwalker^ encounter, continue south and take the elevator down."] = "完成^Valithria Dreamwalker^戰鬥後，繼續向南並乘電梯下行。",
    ["After finishing the adds, proceed forward and defeat ^MOTHER^."] = "完成新增後，繼續前進並擊敗^MOTHER^。",
    ["After getting off the elevator in ^Walk of Kings^, follow the linear path around to ^The Heart of the Empire^."] = "在^Walk of Kings^下電梯後，沿著直線路徑前往^The Heart of the Empire^。",
    ["After getting off the elevator, follow the path around to the map exit labeled ^The Heart of the Empire^."] = "下了電梯後，沿著周圍的路徑前往標有^The Heart of the Empire^的地圖出口。",
    ["After jumping in the hole, engage ^The Fallen Protectors^."] = "跳入洞中後，接合^The Fallen Protectors^。",
    ["After jumping in the hole, follow the path straight ahead to find ^Harjatan^."] = "跳進洞裡後，沿著小路一直向前就能找到^Harjatan^。",
    ["After jumping in the hole, you will be in ^Chamber of Anguish^. Proceed to the next room to find ^Varimathras^."] = "跳入洞後，您將進入^Chamber of Anguish^。前往下一個房間找到 ^Varimathras^。",
    ["After killing ^Alizabal^, visit the final wing on the west to defeat ^Occu'thar^."] = "殺死^Alizabal^後，訪問西邊的最後一個翼樓以擊敗^Occu'thar^。",
    ["After killing ^Anetheron^, talk to ^Lady Jaina Proudmoore^ to continue and she will teleport out. Next, take the long road east until you reach the ^Horde Encampment^."] = "擊殺 ^Anetheron^ 後，與 ^Lady Jaina Proudmoore^ 交談繼續，她隨後會傳送離開。接著沿長路往東，直到抵達 ^Horde Encampment^。",
    ["After killing ^Antoran High Command^, kill yourself by jumping down the elevator hole to save time getting to the next boss."] = "殺死^Antoran High Command^後，跳下電梯洞自殺，以節省到達下一個首領的時間。",
    ["After killing ^Atramedes^, go back out to the main ring and head to the western ring to fight ^Chimaeron^."] = "殺死^Atramedes^後，返回主環並前往西環與^Chimaeron^戰鬥。",
    ["After killing ^Attumen the Huntsman^, backtrack towards the entrance and take the stairs behind ^Berthold^."] = "擊殺 ^Attumen the Huntsman^ 後，原路返回入口方向，並走 ^Berthold^ 身後的樓梯。",
    ["After killing ^Auriaya^, take the southeast exit towards ^The Halls of Winter^. Follow the path counter-clockwise to reach ^Hodir^. See special note for |cffF259C7Hard Mode|r."] = "擊殺^Auriaya^後，從東南出口前往^The Halls of Winter^。沿逆時針方向前進即可到達^Hodir^。請查看|cffF259C7困難模式|r特別提示。",
    ["After killing ^Ayamiss^, head northwest up the stair path until you reach the final boss, ^Ossirian the Unscarred^."] = "擊殺^Ayamiss^後，沿樓梯向西北上行，直到最終首領^Ossirian the Unscarred^。",
    ["After killing ^Baleroc^, interact with the ^Magma Orb^ behind him to open the bridge. Cross the bridge and kill the trash to engage ^Majordomo Staghelm^."] = "殺死^Baleroc^後，與他身後的^Magma Orb^互動以開啟橋梁。過橋並殺死小怪來與^Majordomo Staghelm^交戰。",
    ["After killing ^Battleguard Sartura^, continue north until you reach ^Fankriss the Unyielding^."] = "擊殺^Battleguard Sartura^後, 繼續向北前進，直到抵達^Fankriss the Unyielding^.",
    ["After killing ^Beastlord Darmac^, leave the room and take a right. Follow the path north to reach ^Operator Thogar^. To open the gate and start the fight, kill trash on both platforms, then kill the gunners on the train that pulls up."] = "殺死^Beastlord Darmac^後，離開房間並右轉。沿著小路向北到達^Operator Thogar^。要開啟大門並開始戰鬥，請殺死兩個站台上的小怪，然後殺死停下來的火車上的槍手。",
    ["After killing ^Behemoth^, swim back out the way you came to the map exit labeled ^Halls of the Chosen^."] = "殺死^Behemoth^後，沿著你來到標記為^Halls of the Chosen^的地圖出口的路游回去。",
    ["After killing ^Blade Lord Ta'yak^, take the long stairwell exit on the west side of the room."] = "殺死^Blade Lord Ta'yak^後，從房間西側的長樓梯間出口走。",
    ["After killing ^Blood-Queen Lana'thel^, jump in the hole just south of the boss room."] = "擊殺^Blood-Queen Lana'thel^後，跳入首領房間正南方的洞中。",
    ["After killing ^Broodkeeper Diurna^, click any nearby dragon to fly to the ^Vault of the Incarnates^."] = "殺死^Broodkeeper Diurna^後，點擊附近的任何一條龍飛向^Vault of the Incarnates^。",
    ["After killing ^Broodlord Lashlayer^, continue northwest to find ^Firemaw^ patrolling the path ahead."] = "擊殺^Broodlord Lashlayer^後，繼續向西北前進，在前方路上找到巡邏的^Firemaw^。",
    ["After killing ^Brutallus^, approach ^Felmyst^ nearby to start the next encounter."] = "擊殺 ^Brutallus^ 後，靠近附近的 ^Felmyst^，開始下一場戰鬥。",
    ["After killing ^Carapace^, you will find yourself standing in front of ^N'Zoth^. Attack the boss to start the encounter."] = "殺死^Carapace^後，你會發現自己站在^N'Zoth^前面。攻擊 首領 以開始戰鬥。",
    ["After killing ^Cenarius^, jump into the portal behind him to reach the ^Rift of Aln^."] = "殺死^Cenarius^後，跳入他身後的傳送門到達^Rift of Aln^。",
    ["After killing ^Chromaggus^, exit northeast and follow the path to the next room. Talk to ^Lord Victor Nefarius^ to begin the final encounter against ^Nefarian^."] = "擊殺^Chromaggus^後，從東北離開並沿路進入下一個房間。與^Lord Victor Nefarius^交談，開始與^Nefarian^的最終戰鬥。",
    ["After killing ^Chronomatic Anomaly^, proceed up the stairwell at the northwest side of the room, and clear slimes in the boss room to engage ^Trilliax^."] = "殺死 ^Chronomatic Anomaly^ 後，沿著房間西北側的樓梯井前進，清除 首領 房間中的史萊姆，與 ^Trilliax^ 交戰。",
    ["After killing ^Council of Blood^, take the south stairwell out of the room and return to the ^Halls of the Faithful^."] = "殺死^Council of Blood^後，從南樓梯間離開房間並返回^Halls of the Faithful^。",
    ["After killing ^Council of Dreams^, follow the path behind them to reach ^Nymue, Weaver of the Cycle^."] = "殺死^Council of Dreams^後，沿著他們身後的路徑到達^Nymue, Weaver of the Cycle^。",
    ["After killing ^Dathea, Ascended^, take one of the nearby ^Downward Draft^ to return below to ^The Primal Bulwark^."] = "殺死^Dathea, Ascended^後，拿附近的^Downward Draft^之一返回下面的^The Primal Bulwark^。",
    ["After killing ^Dausegne^, continue up the path toward ^The Endless Foundry^."] = "殺死 ^Dausegne^ 後，繼續沿著通往 ^The Endless Foundry^ 的路徑前進。",
    ["After killing ^Deathbringer Saurfang^, enter the building behind him."] = "擊殺^Deathbringer Saurfang^後，進入他身後的建築。",
    ["After killing ^Drest'agath^, leave the room and continue down the spiral toward the map exit ^Chamber of Rebirth^."] = "殺死^Drest'agath^後，離開房間並繼續沿著螺旋走向地圖出口^Chamber of Rebirth^。",
    ["After killing ^Elegon^, follow the path out of the room and head south to arrive at the next boss room. To start the fight with ^Will of the Emperor^, click the pipes below (^Heroic^) or click the console (^Normal/LFR^)."] = "殺死^Elegon^後，沿著房間外的小路向南走，到達下一個首領房間。要與 ^Will of the Emperor^ 開始戰鬥，請點擊下面的管道 (^Heroic^) 或點擊控制台 (^Normal/LFR^)。",
    ["After killing ^Eranog^, click the ^Clutchwarren Runestone^ next to each staircase. After that, take the staircase towards ^The Clutchwarren^."] = "殺死^Eranog^後，點擊每個樓梯旁邊的^Clutchwarren Runestone^。之後，走樓梯前往 ^The Clutchwarren^。",
    ["After killing ^Eranog^, take the left map exit labeled ^The Elemental Conclave^."] = "殺死^Eranog^後，從左側地圖出口標記為^The Elemental Conclave^。",
    ["After killing ^Eranog^, there are 3 paths available. Take the path on the right labeled ^The Vault Approach^."] = "殺死^Eranog^後，有3條路徑可用。走右側標記為 ^The Vault Approach^ 的路徑。",
    ["After killing ^Eranog^, you will find two clickable runes beside the stairs leading to ^Broodkeeper Diurna^. Click the runes to open the access."] = "殺死^Eranog^後，你會在通往^Broodkeeper Diurna^的樓梯旁邊發現兩個可點擊的符文。點擊符文以開啟訪問權限。",
    ["After killing ^Fallen Avatar^, continue straight ahead across the slime to the map exit labeled ^The Twisting Nether^. Walk into the green swirly portal."] = "殺死 ^Fallen Avatar^ 後，繼續向前穿過史萊姆到達標記為 ^The Twisting Nether^ 的地圖出口。走進綠色的漩渦傳送門。",
    ["After killing ^Fankriss^, continue southwest until you reach ^Princess Huhuran^."] = "擊殺^Fankriss^後, 繼續向西南前進，直到抵達^Princess Huhuran^.",
    ["After killing ^Fankriss^, take the northeast tunnel out of the room. When you reach the clearing, climb the spiraling walkway to reach ^Viscidus^."] = "擊殺^Fankriss^後，從東北隧道離開房間。到達空地後，沿螺旋通道上行前往^Viscidus^。",
    ["After killing ^Fatescribe Roh-Kalo^, go back out the way you came and follow the path to ^Kel'Thuzad^."] = "殺死 ^Fatescribe Roh-Kalo^ 後，按原路返回，沿著路徑前往 ^Kel'Thuzad^。",
    ["After killing ^Felmyst^, go up the northeast ramp and follow the looping path all the way to ^Eredar Twins^."] = "擊殺 ^Felmyst^ 後，沿東北斜坡上去，沿環形路線一直前往 ^Eredar Twins^。",
    ["After killing ^Feng^, continue on to the next area."] = "殺死^Feng^後，繼續前往下一個區域。",
    ["After killing ^Fetid Devourer^, go back the way you came to arrive back in the ^Ring of Containment^."] = "殺死^Fetid Devourer^後，按原路返回^Ring of Containment^。",
    ["After killing ^Flamegor^, continue southeast into the next room to find a lever. Pull it to release ^Chromaggus^."] = "擊殺^Flamegor^後，向東南進入下一個房間並找到控制桿。拉動它釋放^Chromaggus^。",
    ["After killing ^Galakras^, follow the long path to the west until you arrive at ^Iron Juggernaut^."] = "殺死^Galakras^後，沿著漫長的道路向西行進，直到到達^Iron Juggernaut^。",
    ["After killing ^Gara'jal^, follow the linear path to ^Lorewalker Cho^. Speak to him to trigger a series of trash encounters."] = "殺死 ^Gara'jal^ 後，沿著線性路徑到達 ^Lorewalker Cho^。與他交談會引發一系列小怪戰鬥。",
    ["After killing ^Garalon^, walk up the stairs behind you to find ^Wind Lord Mel'jarak^."] = "殺死^Garalon^後，走上你身後的樓梯找到^Wind Lord Mel'jarak^。",
    ["After killing ^Garothi Worldbreaker^, you can take the teleporter to whichever skip you have unlocked:\n  - The Exhaust: ^Imonar the Soulhunter^\n  - The Burning Throne: ^Aggramar^\n\nNote: RetroRuns only has the route built for Aggramar at this time."] = "擊殺 ^Garothi Worldbreaker^ 後，你可以通過傳送器前往已解鎖的任一捷徑：\n  - 排氣口：^Imonar the Soulhunter^\n  - 燃燒王座：^Aggramar^\n\n注意：RetroRuns 目前只提供通往阿格拉瑪的路線。",
    ["After killing ^Garr^, head southeast to reach ^Shazzrah^."] = "擊殺^Garr^後, 向東南前進，直到抵達^Shazzrah^.",
    ["After killing ^Gluth^, follow the path straight ahead to reach ^Thaddius^."] = "擊殺 ^Gluth^ 後，沿路直行前往 ^Thaddius^。",
    ["After killing ^Gnarlroot^ and ^Igira^, you can channel the seed to open the bridge to ^Smolderon^."] = "殺死 ^Gnarlroot^ 和 ^Igira^ 後，您可以引導種子以開啟通往 ^Smolderon^ 的橋。",
    ["After killing ^Gnarlroot^, continue forward and clear the trash pack to start the encounter with ^Igira the Cruel^."] = "殺死^Gnarlroot^後，繼續前進並清除小怪群，開始與^Igira the Cruel^的戰鬥。",
    ["After killing ^Golemagg the Incinerator^, backtrack up the ramp to reach ^Majordomo Executus^."] = "擊殺^Golemagg the Incinerator^後，沿斜坡原路返回上層前往^Majordomo Executus^。",
    ["After killing ^Gorefiend^, click the nearby portal."] = "殺死^Gorefiend^後，點擊附近的傳送門。",
    ["After killing ^Goroth^, go down the staircase behind ^Image of Aegwynn^."] = "殺死^Goroth^後，從^Image of Aegwynn^後面的樓梯下去。",
    ["After killing ^Goroth^, take the western exit labeled ^The Abyssal Throne^."] = "殺死^Goroth^後，從標有^The Abyssal Throne^的西出口走。",
    ["After killing ^Goroth^, the door behind ^Image of Aegwynn^ opens, allowing you to skip to ^Maiden of Vigilance^."] = "殺死^Goroth^後，^Image of Aegwynn^後面的門開啟，讓你跳到^Maiden of Vigilance^。",
    ["After killing ^Grong^, continue up the stairwell behind him towards the map exit labeled ^Halls of Opulence^. Jump in the hole when you reach the end of the path."] = "殺死 ^Grong^ 後，繼續沿著他身後的樓梯井朝標記為 ^Halls of Opulence^ 的地圖出口走去。當你到達路徑的盡頭時，跳進洞裡。",
    ["After killing ^Gruul^, backtrack to the bridge and go east. Follow the spiral down, then at the bottom go straight ahead to locate ^The Blast Furnace^."] = "殺死^Gruul^後，原路返回橋並向東走。沿著螺旋向下，然後在底部直行找到^The Blast Furnace^。",
    ["After killing ^Guardian of the First Ones^, go back the way you came and follow the path to ^Fatescribe Roh-Kalo^. For a shortcut, you can jump off the ledge to respawn halfway there."] = "殺死^Guardian of the First Ones^後，按原路返回，沿著路徑前往^Fatescribe Roh-Kalo^。為了走捷徑，你可以跳下壁架，在半路重生。",
    ["After killing ^Guarm^, continue down the path to meet ^Helya^. Kill the trash to start the encounter."] = "殺死^Guarm^後，繼續沿著路徑遇見^Helya^。殺死小怪來開始戰鬥。",
    ["After killing ^Gurtogg Bloodboil^, go up the stairs just east of his corpse. When you reach the top, go south until you reach ^Reliquary of Souls^."] = "擊殺 ^Gurtogg Bloodboil^ 後，走他屍體正東邊的樓梯。到頂端後往南走，直到抵達 ^Reliquary of Souls^。",
    ["After killing ^Halondrus^, continue down the path behind him to reach his loot chest. Activate the nearby teleporter and select ^Genesis Cradle Alpha^."] = "殺死^Halondrus^後，繼續沿著他身後的路徑到達他的戰利品箱。啟動附近的傳送器並選擇 ^Genesis Cradle Alpha^。",
    ["After killing ^Hans'gar and Franzok^, take the southern exit out of the room. Follow the path across the next room to reach ^Flamebender Ka'graz^."] = "殺死^Hans'gar and Franzok^後，從南出口離開房間。沿著路徑穿過下一個房間到達^Flamebender Ka'graz^。",
    ["After killing ^Harjatan^, jump over the ledge to his left and land in the water. Follow the path through the tunnel and continue straight ahead to find ^Mistress Sassz'ine^."] = "殺死^Harjatan^後，跳過他左邊的壁架並落入水中。沿著隧道的小路繼續直行即可找到^Mistress Sassz'ine^。",
    ["After killing ^High Astromancer Solarian^, backtrack out of the room and head north to find ^Kael'thas Sunstrider^."] = "擊殺 ^High Astromancer Solarian^ 後，原路離開房間並往北尋找 ^Kael'thas Sunstrider^。",
    ["After killing ^Horridon^, go through the north exit and follow the path all the way to ^Council of Elders^. Kill trash to unlock doors along the way."] = "殺掉^Horridon^後，從北口出來，沿著小路一直走到^Council of Elders^。消滅小怪以開啟沿途的門。",
    ["After killing ^Hungering Destroyer^, take the stairs going up to ^The Purloined Stores^."] = "殺死^Hungering Destroyer^後，走樓梯前往^The Purloined Stores^。",
    ["After killing ^Huntsman Altimor^, follow the path to a small room at the back, and jump into the sewer that the NPCs are standing next to. Make your way down the path to find ^Hungering Destroyer^."] = "擊殺 ^Huntsman Altimor^ 後，沿路前往後方的小房間，跳進 NPC 旁邊的下水道。沿路向下前往 ^Hungering Destroyer^。",
    ["After killing ^Igira the Cruel^, go up the stairs behind him and channel the ^Formation Seed^ to form the bridge."] = "殺死 ^Igira the Cruel^ 後，上他身後的樓梯並引導 ^Formation Seed^ 形成橋梁。",
    ["After killing ^Igira^, take the left exit to ^The Scorched Hall^."] = "殺死^Igira^後，從左側出口前往^The Scorched Hall^。",
    ["After killing ^Ignis^, mount up and backtrack up the path straight ahead to ^Razorscale^. Talk to ^Expedition Commander^ to begin the fight."] = "擊殺^Ignis^後，騎上坐騎並沿正前方的道路原路返回^Razorscale^。與^Expedition Commander^交談以開始戰鬥。",
    ["After killing ^Il'gynoth^, return back the way you came, through the portal to ^Core of the Nightmare^."] = "殺死 ^Il'gynoth^ 後，按原路返回，通過傳送門到達 ^Core of the Nightmare^。",
    ["After killing ^Imonar^, make your way down the long path to find the next boss, ^Kin'garoth^."] = "殺死^Imonar^後，沿著漫長的道路尋找下一個首領，^Kin'garoth^。",
    ["After killing ^Iron Juggernaut^, head into the ^Gates of Orgrimmar^."] = "殺死^Iron Juggernaut^後，進入^Gates of Orgrimmar^。",
    ["After killing ^Iron Reaver^, continue up the stairs behind him to the next area."] = "殺死^Iron Reaver^後，繼續上他身後的樓梯到下一個區域。",
    ["After killing ^Ji-Kun^, click a feather followed by your Extra Action Button to fly to the southwest exit of the room."] = "殺死^Ji-Kun^後，點擊一根羽毛，然後點擊你的額外快捷鍵，飛到房間的西南出口。",
    ["After killing ^Jin'rokh^, take the long path south and cross two bridges before arriving in the next area. Avoid blue circles; they will throw you off the edge."] = "殺死^Jin'rokh^後，沿著長路向南走，穿過兩座橋，然後到達下一個區域。避免藍色圓圈；他們會把你扔到懸崖邊。",
    ["After killing ^Kargath^, exit the room to the northwest and follow the path around to ^The Butcher^."] = "殺死^Kargath^後，從西北方向退出房間，沿著周圍的路徑到達^The Butcher^。",
    ["After killing ^Kaz'rogal^, talk to ^Thrall^ again to start the encounter against ^Azgalor^."] = "擊殺 ^Kaz'rogal^ 後，再次與 ^Thrall^ 交談，開始與 ^Azgalor^ 的戰鬥。",
    ["After killing ^Kazzara^, take the left path towards the exit labeled ^Onyx Laboratory^."] = "殺死 ^Kazzara^ 後，沿左側路徑前往標記為 ^Onyx Laboratory^ 的出口。",
    ["After killing ^Kel'Thuzad^, take the purple portal that appeared right behind him."] = "殺死^Kel'Thuzad^後，採取出現在他身後的紫色傳送門。",
    ["After killing ^Kilrogg Deadeye^, exit behind him to the east and follow the path out of this area."] = "殺死^Kilrogg Deadeye^後，從他身後向東退出並沿著路徑離開該區域。",
    ["After killing ^Kin'garoth^, click the ^Lightforged Beacon^ behind you to be teleported to the next area. Select ^The Burning Throne^ from the dialog options."] = "擊殺^Kin'garoth^後，點擊身後的^Lightforged Beacon^即可傳送到下一個區域。從對話框選項中選擇 ^The Burning Throne^。",
    ["After killing ^Ko'ragh^, take the northwest stairwell out of the room."] = "殺死^Ko'ragh^後，從西北樓梯間走出房間。",
    ["After killing ^Kor'kron Dark Shaman^, follow the northeastern path towards ^The Drag^. Clear trash and enter the ^Cleft of Shadows^."] = "殺死^Kor'kron Dark Shaman^後，沿著東北方向前往^The Drag^。清除小怪並輸入 ^Cleft of Shadows^。",
    ["After killing ^Kormrok^, exit the room the way you entered."] = "殺死^Kormrok^後，按照你進入的方式退出房間。",
    ["After killing ^Kromog^, exit the room to the east and follow the path to the elevator."] = "殺死^Kromog^後，從東邊退出房間，沿著路徑前往電梯。",
    ["After killing ^Kurog Grimtotem^, follow the path back to ^The Vault Approach^."] = "殺死 ^Kurog Grimtotem^ 後，按照路徑返回 ^The Vault Approach^。",
    ["After killing ^Lady Ashvane^, jump through the hole in the middle of her boss room to land in ^The Traverse^."] = "殺死^Lady Ashvane^後，從她的首領房間中間的洞跳到降落在^The Traverse^。",
    ["After killing ^Lady Inerva Darkvein^, follow the path to take the exit ^General Draven^ is standing in. He will lead you back to the main entrance of the raid in ^The Grand Walk^."] = "殺死^Lady Inerva Darkvein^後，沿著路徑走到^General Draven^所在的出口。他會帶你回到^The Grand Walk^的副本正門。",
    ["After killing ^Larodar^, interact with the ^Seed of Life^ to unlock a portal at the back of the room. Walk through the portal to arrive back at the ^Wellspring Atrium^."] = "殺死 ^Larodar^ 後，與 ^Seed of Life^ 交互以解鎖房間後面的傳送門。穿過傳送門回到^Wellspring Atrium^。",
    ["After killing ^Lei Shen^, click the ^Displacement Pad^ in the middle of the room to be teleported back to ^Primordius^' room."] = "殺死^Lei Shen^後，點擊房間中間的^Displacement Pad^即可傳送回^Primordius^'房間。",
    ["After killing ^Leotheras the Blind^, take the eastern exit from the room and follow the path around to find ^Fathom-Lord Karathress^."] = "擊殺 ^Leotheras the Blind^ 後，從房間東側出口離開，沿路繞行尋找 ^Fathom-Lord Karathress^。",
    ["After killing ^Loatheb^, click on the ^Naxxramas Portal^ to be teleported back to the entrance."] = "擊殺 ^Loatheb^ 後，點擊 ^Naxxramas Portal^ 傳送回入口。",
    ["After killing ^Lord Marrowgar^, go up the ramp behind him and follow the path to ^Lady Deathwhisper^."] = "擊殺^Lord Marrowgar^後，沿他身後的坡道上行，再沿路前往^Lady Deathwhisper^。",
    ["After killing ^Lord Rhyolith^, make your way north to reach ^Alysrazor^. Tag ^Majordomo^ to start the encounter."] = "殺死^Lord Rhyolith^後，向北到達^Alysrazor^。標記 ^Majordomo^ 以開始戰鬥。",
    ["After killing ^Lords of Dread^, you will find a teleporter behind them. Use it to take a shortcut back to the beginning of the room, and follow the path to ^Rygelon^."] = "殺死^Lords of Dread^後，你會發現他們身後有一個傳送器。使用它可以走捷徑回到房間的開頭，然後沿著路徑前往^Rygelon^。",
    ["After killing ^Lucifron^, continue north to reach ^Magmadar^."] = "擊殺^Lucifron^後, 繼續向北前進，直到抵達^Magmadar^.",
    ["After killing ^M'uru^, proceed southwest down the ramp until you reach the Sunwell to face ^Kil'jaeden^. Clear the trash to start the encounter."] = "擊殺 ^M'uru^ 後，沿斜坡往西南下去，直到抵達太陽之井並面對 ^Kil'jaeden^。清掉小怪即可開始戰鬥。",
    ["After killing ^Maexxna^, click the ^Naxxramas Portal^ to return to the entrance."] = "擊殺 ^Maexxna^ 後，點擊 ^Naxxramas Portal^ 返回入口。",
    ["After killing ^Magmaw^, go back down the stairs to the main lobby. Take a left and ride the elevator down."] = "殺死^Magmaw^後，下樓梯回到主大廳。向左轉，乘電梯下去。",
    ["After killing ^Maiden of Vigilance^, click the nearby ^Teleportation Pad^ to be taken to ^Chamber of the Avatar^. Note: the pad will likely be under the boss corpse until she despawns, but you can still click it."] = "殺死^Maiden of Vigilance^後，點擊附近的^Teleportation Pad^即可前往^Chamber of the Avatar^。注意：墊子可能會位於 首領 屍體下方，直到她消失，但您仍然可以點擊它。",
    ["After killing ^Majordomo Staghelm^, proceed straight ahead all the way to ^Ragnaros^."] = "殺掉^Majordomo Staghelm^後，一直往前走到^Ragnaros^。",
    ["After killing ^Malkorok^, take the northwestern exit from the platform and follow it around to kill the scorpion and click ^Release Lever^."] = "殺死^Malkorok^後，從平台的西北出口走，沿著它繞過去殺死蠍子，然後點擊^Release Lever^。",
    ["After killing ^Mannoroth^, click the nearby portal."] = "殺死^Mannoroth^後，點擊附近的傳送門。",
    ["After killing ^Maut^, take the long path all the way to the right to reach ^The Prophet Skitra^. Jump off the ledge and die for a shortcut."] = "殺死^Maut^後，沿著長路一直向右到達^The Prophet Skitra^。從壁架上跳下來，為捷徑而死。",
    ["After killing ^Mimiron^, backtrack south to the ^Ulduar Teleporter^. Select ^Conservatory of Life^."] = "擊殺^Mimiron^後，向南原路返回^Ulduar Teleporter^，選擇^Conservatory of Life^。",
    ["After killing ^Moam^, travel far southeast until you reach ^Buru the Gorger^."] = "擊殺^Moam^後, 向東南前進，直到抵達^Buru the Gorger^.",
    ["After killing ^Moroes^, backtrack to ^The Grand Ballroom^ and climb the stairwell on the north end of the room."] = "擊殺 ^Moroes^ 後，原路返回 ^The Grand Ballroom^，並從房間北端的樓梯上去。",
    ["After killing ^Netherspite^, backtrack to the Ethereal room and take the ramp down this time. Open the ^Gamesman's Hall Door^ to reach the next area. There is a vendor NPC nearby if you need to clear bag space."] = "擊殺 ^Netherspite^ 後，原路返回伊斯利房間，這次沿斜坡下去。打開 ^Gamesman's Hall Door^ 進入下一區域。如果需要清理背包空間，附近有一個商人 NPC。",
    ["After killing ^Nymue^, walk up the stairs behind her to interact with the ^Seed of Life^. This opens a portal at the back of the room. Walk through the portal to return back to ^Wellspring Atrium^."] = "殺死^Nymue^後，走上她身後的樓梯與^Seed of Life^互動。這會在房間後面開啟一個傳送門。穿過傳送門返回^Wellspring Atrium^。",
    ["After killing ^Opulence^, exit the room to the north, up some stairs to the map exit labeled ^Loa's Sanctum^."] = "殺死 ^Opulence^ 後，從北面退出房間，爬上一些樓梯到達標有 ^Loa's Sanctum^ 的地圖出口。",
    ["After killing ^Opulence^, follow the path straight ahead and make your way to the map exit labeled ^Loa's Sanctum^."] = "殺死^Opulence^後，沿著路徑一直向前，到達標記為^Loa's Sanctum^的地圖出口。",
    ["After killing ^Oregorger^, leave his area the way you came and follow the path all the way north to find ^Gruul^."] = "殺死 ^Oregorger^ 後，按照來時的路線離開他的區域，沿著小路一直向北找到 ^Gruul^。",
    ["After killing ^Orgozoa^, travel to the far west to reach the map exit labeled ^The Queen's Court^. You will be swimming for a good portion of this journey."] = "殺死 ^Orgozoa^ 後，向最西邊移動，到達標記為 ^The Queen's Court^ 的地圖出口。這段旅程的大部分時間您都將在水中游泳。",
    ["After killing ^Painsmith Raznal^, walk out the new exit to the West and walk through the portal."] = "殺死^Painsmith Raznal^後，走出新的出口向西，穿過傳送門。",
    ["After killing ^Patchwerk^, follow the path and take a right to reach ^Grobbulus^."] = "擊殺 ^Patchwerk^ 後，沿路前進並右轉前往 ^Grobbulus^。",
    ["After killing ^Portal Keeper Hasabel^, return to the portal marked on the map as ^Light's Breach^."] = "殺死^Portal Keeper Hasabel^後，返回地圖上標記為^Light's Breach^的傳送門。",
    ["After killing ^Primordius^, take the western stairwell out of the room and follow it to ^Dark Animus^. Kill the ritualists to start the fight."] = "殺死^Primordius^後，將西邊的樓梯井帶出房間，然後沿著它到達^Dark Animus^。殺死儀式者開始戰鬥。",
    ["After killing ^Princess Huhuran^, travel southeast until you reach ^The Twin Emperors^."] = "擊殺^Princess Huhuran^後, 向東南前進，直到抵達^The Twin Emperors^.",
    ["After killing ^Razorscale^, return to the main path and go north to reach ^XT-002 Deconstructor^. See special note for |cffF259C7Hard Mode|r."] = "擊殺^Razorscale^後，返回主路並向北前往^XT-002 Deconstructor^。請查看|cffF259C7困難模式|r特別提示。",
    ["After killing ^Remnant of Ner'zhul^, follow the path to loop back around to ^Painsmith Raznal^."] = "殺死 ^Remnant of Ner'zhul^ 後，按照路徑循環回到 ^Painsmith Raznal^。",
    ["After killing ^Rotface^, click the ^Ooze Release Valve^ on the right side of the exit door. Then follow the path to ^Professor Putricide^."] = "擊殺^Rotface^後，點擊出口門右側的^Ooze Release Valve^，然後沿路前往^Professor Putricide^。",
    ["After killing ^Rygelon^, follow the path straight behind him all the way to ^The Jailer^."] = "殺死^Rygelon^後，沿著他身後的路一直走到^The Jailer^。",
    ["After killing ^Sapphiron^, take the west exit and follow the path around to ^Kel'Thuzad^. Walk into the middle circle to begin the encounter."] = "擊殺 ^Sapphiron^ 後，從西側出口離開並沿路前往 ^Kel'Thuzad^。走入中央圓環以開始戰鬥。",
    ["After killing ^Sennarth^, click the ^Gust of Wind^ behind him to return to the bottom of the room. If you killed him on the ground floor, proceed up the ramp to find his corpse and collect his loot!"] = "殺死^Sennarth^後，點擊他身後的^Gust of Wind^返回房間底部。如果您在一樓殺死了他，請爬上坡道找到他的屍體並收集他的戰利品！",
    ["After killing ^Shadow-Lord Iskar^, exit the room to the east. At the first intersection, go south to the next area."] = "殺死^Shadow-Lord Iskar^後，從東邊退出房間。在第一個路口，向南前往下一個區域。",
    ["After killing ^Shazzrah^, you will find ^Baron Geddon^ patrolling the northeast path."] = "擊殺^Shazzrah^後，你會在東北路徑上找到巡邏的^Baron Geddon^。",
    ["After killing ^Shriekwing^, follow the north path out of the room and go down the stairs. Kill the trash, and ^General Draven^ will come open the gate. Kill a few trash mobs then engage ^Huntsman Altimor^."] = "殺死^Shriekwing^後，沿著北邊的小路走出房間，下樓梯。殺死小怪，^General Draven^ 就會開啟大門。殺死一些小怪小怪，然後與 ^Huntsman Altimor^ 交戰。",
    ["After killing ^Shriekwing^, speak to ^General Draven^ near the north exit to skip to ^Sludgefist^. He will spawn behind you in the normal location."] = "殺死^Shriekwing^後，與北出口附近的^General Draven^交談以跳至^Sludgefist^。他會在你身後的正常位置重生。",
    ["After killing ^Shriekwing^, there will be a lengthy dialog. After that, you can fight ^Sludgefist^ in the same room."] = "殺死^Shriekwing^後，會出現一個冗長的對話框。之後，你可以在同一個房間裡與^Sludgefist^戰鬥。",
    ["After killing ^Sindragosa^, backtrack slightly up the stairs and head up the western ramp to reach a ^Scourge Transporter^. Use it to teleport to ^Upper Spire^."] = "擊殺^Sindragosa^後，沿樓梯稍微返回，再走上西側坡道找到^Scourge Transporter^。使用它傳送到^Upper Spire^。",
    ["After killing ^Skitra^, backtrack a bit and go north to the map exit labeled ^Ny'alotha^. Ride an elevator up, and kill the trash to open the path to the next area."] = "殺死^Skitra^後，原路返回，向北前往標記為^Ny'alotha^的地圖出口。乘坐電梯上去，殺死小怪以開啟通往下一個區域的道路。",
    ["After killing ^Sludgefist^, travel up the stairs behind him and walk through the mirror teleporter to land in ^Nightcloak Sanctum^."] = "殺死^Sludgefist^後，爬上他身後的樓梯，穿過鏡子傳送器降落在^Nightcloak Sanctum^。",
    ["After killing ^Smolderon^, talk to the dragon to be flown to ^Tindral Sageswift, Seer of the Flame^."] = "殺死 ^Smolderon^ 後，與龍交談即可飛向 ^Tindral Sageswift, Seer of the Flame^。",
    ["After killing ^Soulrender Dormazain^, follow the path to ^Remnant of Ner'zhul^. Kill the trash to engage the boss."] = "殺死^Soulrender Dormazain^後，按照路徑到達^Remnant of Ner'zhul^。殺死小怪來對付首領。",
    ["After killing ^Stone Legion Generals^, simply walk into the room where ^Sire Denathrius^ is waiting for you."] = "殺死^Stone Legion Generals^後，只需走進^Sire Denathrius^正在等你的房間。",
    ["After killing ^Sulfuron Harbinger^, go north and west to ^Golemagg the Incinerator^."] = "擊殺^Sulfuron Harbinger^後，向北再向西前往^Golemagg the Incinerator^。",
    ["After killing ^Taloc^, the floor will start to descend. Once you reach the bottom, go straight ahead and click the ^Titan Console^."] = "殺死^Taloc^後，地板將開始下降。到達底部後，直接向前並點擊 ^Titan Console^。",
    ["After killing ^Tarragrue^, wait for dialog to complete, then walk through the portal marked as a map exit ^Shadowsteel Foundry^."] = "殺死 ^Tarragrue^ 後，等待對話框完成，然後穿過標記為地圖出口 ^Shadowsteel Foundry^ 的傳送門。",
    ["After killing ^Teron Gorefiend^, backtrack towards the main concourse."] = "擊殺 ^Teron Gorefiend^ 後，原路返回主大廳。",
    ["After killing ^The Amalgamation Chamber^, follow the path north to reach some stairs leading to the ^Molten Crucible^."] = "殺死^The Amalgamation Chamber^後，沿著小路向北到達通往^Molten Crucible^的樓梯。",
    ["After killing ^The Butcher^, follow the path to the west to reach ^Tectus^. Kill the (3) rock golems to spawn the boss."] = "殺死^The Butcher^後，沿著小路向西到達^Tectus^。殺死 (3) 個岩石傀儡來出現 首領。",
    ["After killing ^The Curator^, proceed past him and follow the ramps through the library."] = "擊殺 ^The Curator^ 後，從他身邊繼續前進，沿斜坡穿過圖書館。",
    ["After killing ^The Eye of the Jailer^, follow the path all the way north to find ^The Nine^."] = "殺死^The Eye of the Jailer^後，沿著小路一路向北找到^The Nine^。",
    ["After killing ^The Hivemind^, continue past them to the next room, and take the elevator up to the ^Terrace of Desolation^."] = "殺死^The Hivemind^後，繼續經過他們到下一個房間，然後乘電梯到^Terrace of Desolation^。",
    ["After killing ^The Illidari Council^, talk to ^Akama^ and follow him up the ramp. After some dialog, he will open the door to the final area."] = "擊殺 ^The Illidari Council^ 後，與 ^Akama^ 交談並跟隨他上坡。經過一段對話後，他會打開通往最終區域的門。",
    ["After killing ^The Lurker Below^, go up a nearby ramp and work your way up the path to ^Leotheras the Blind^."] = "擊殺 ^The Lurker Below^ 後，沿附近的斜坡上去，再沿路往上前往 ^Leotheras the Blind^。",
    ["After killing ^The Nine^, take the elevator to the left. You will arrive at ^The Torment Chambers^."] = "殺死^The Nine^後，乘電梯到左邊。您將到達^The Torment Chambers^。",
    ["After killing ^The Primal Council^, follow the path towards the exit labeled ^Galewind Crag^. Kill ^Thondrozus^, and click on ^Upward Draft^ to be carried up to ^Galewind Crag^. Approach the Downward Draft."] = "殺死 ^The Primal Council^ 後，沿著標記為 ^Galewind Crag^ 的出口前進。殺掉^Thondrozus^，然後點擊^Upward Draft^就會被帶到^Galewind Crag^。接近向下吃水。",
    ["After killing ^The Prophet Skeram^, climb the stairs behind him. After the fork, make your way down some stairs on your way underneath the platform you just walked across."] = "擊殺^The Prophet Skeram^後，走他身後的樓梯。經過岔路後，下幾級樓梯，從剛剛走過的平台下方通過。",
    ["After killing ^The Tarragrue^, speak to the ^Ebon Blade Acolyte^ NPC located inside the boss room. He will conjure a portal that will send you straight to ^Kel'Thuzad^."] = "擊殺 ^The Tarragrue^ 後，與首領房間內的 ^Ebon Blade Acolyte^ NPC 交談。他會召喚一個傳送門，將你直接送到 ^Kel'Thuzad^。",
    ["After killing ^Theralion and Valiona^, head south and exit this area."] = "殺死^Theralion and Valiona^後，向南走並退出該區域。",
    ["After killing ^Tichondrius^, backtrack the way you came to return to the main courtyard."] = "殺死^Tichondrius^後，原路返回主庭院。",
    ["After killing ^Tindral^, mount up and fly into the fire-colored portal in the sky (marked with a |TInterface\\TargetingFrame\\UI-RaidTargetingIcon_1:0|t). This will teleport you to ^Heart of Amirdrassil^."] = "擊敗 ^Tindral^ 後，騎上坐騎並飛入空中火焰色的傳送門（以 |TInterface\\TargetingFrame\\UI-RaidTargetingIcon_1:0|t 標記）。這會將你傳送到 ^Heart of Amirdrassil^。",
    ["After killing ^Tyrant Velhari^, leave the room to the west and proceed up the path to the north."] = "殺死^Tyrant Velhari^後，離開西邊的房間，沿著小路向北走。",
    ["After killing ^Ursoc^, go back the way you came and go back through the portal to ^Core of the Nightmare^."] = "殺死^Ursoc^後，按原路返回，通過傳送門返回^Core of the Nightmare^。",
    ["After killing ^Vectis^, go back the way you came to arrive back in the ^Ring of Containment^."] = "殺死^Vectis^後，按原路返回^Ring of Containment^。",
    ["After killing ^Vexiona^, interact with the ^Re-origination Anchor^ behind the boss to be teleported. After you land, continue ahead."] = "擊殺^Vexiona^後，與首領身後的^Re-origination Anchor^互動即可傳送。落地後繼續前行。",
    ["After killing ^Vigilant Guardian^, proceed up the bridge and speak to ^Highlord Bolvar Fordragon^ and then take the portal to ^Domination's Grasp^."] = "殺死^Vigilant Guardian^後，繼續走上橋並與^Highlord Bolvar Fordragon^交談，然後通過傳送門到達^Domination's Grasp^。",
    ["After killing ^Vigilant Guardian^, proceed up the bridge and speak to ^Highlord Bolvar Fordragon^ near the teleporter to skip ahead to ^Anduin Wrynn^."] = "殺死 ^Vigilant Guardian^ 後，繼續上橋並與傳送器附近的 ^Highlord Bolvar Fordragon^ 交談以跳至 ^Anduin Wrynn^。",
    ["After killing ^Volcoross^, continue down the path behind him. Clear trash to start the encounter with ^Larodar, Keeper of the Flame^."] = "殺死^Volcoross^後，繼續沿著他身後的路走。清除小怪以開始與 ^Larodar, Keeper of the Flame^ 的戰鬥。",
    ["After killing ^Warmaster Blackhorn^, talk to ^Sky Captain Swayze^ to begin the encounter with ^Spine of Deathwing^."] = "殺死^Warmaster Blackhorn^後，與^Sky Captain Swayze^交談以開始與^Spine of Deathwing^的戰鬥。",
    ["After killing ^Wrathion^, take the path all the way to the left. Clear the room to spawn ^Maut^, and kill him."] = "殺死^Wrathion^後，沿著路徑一直向左走。清理房間以出現^Maut^，並殺死他。",
    ["After killing ^Xanesh^, leave the room to the east and towards the map exit for ^Twilight Landing^. Ride the elevator up."] = "殺死^Xanesh^後，離開房間向東，走向^Twilight Landing^的地圖出口。乘電梯上去。",
    ["After killing ^Xhul'horac^, head west out of the room the same way you came in."] = "殺死^Xhul'horac^後，按照進來時的路線向西走出房間。",
    ["After killing ^Xhul'horac^, take the portal that appears right next to you."] = "殺死 ^Xhul'horac^ 後，進入出現在你旁邊的傳送門。",
    ["After killing ^Za'qul^, watch a brief dialog while waiting on a portal to spawn behind the boss. Take the portal, marked on the map as an exit labeled ^The Last Prison^."] = "殺死 ^Za'qul^ 後，在等待 首領 後面出現傳送門時觀看簡短的對話。進入地圖上標記為 ^The Last Prison^ 的出口的傳送門。",
    ["After killing ^Zek'voz^, go back the way you came to arrive back in the ^Ring of Containment^."] = "殺死^Zek'voz^後，按原路返回^Ring of Containment^。",
    ["After killing ^Zor'lok^, take the northwest stairwell and follow the path into the next room to find ^Blade Lord Ta'yak^. Kill trash in all 4 corners to begin the fight."] = "殺死^Zor'lok^後，走西北樓梯間，沿著小路進入下一個房間找到^Blade Lord Ta'yak^。殺死所有 4 個角落的小怪即可開始戰鬥。",
    ["After killing ^Zul^, activate the ^Titan Console^ on the south end of the platform. Then jump into ^The Festering Core^ to fight ^Mythrax the Unraveler^."] = "殺死^Zul^後，啟動平台南端的^Titan Console^。然後跳入^The Festering Core^與^Mythrax the Unraveler^戰鬥。",
    ["After killing both ^Skolex^ and ^Artificer Xy'mox^, follow the path south to ^Halondrus^."] = "殺死 ^Skolex^ 和 ^Artificer Xy'mox^ 後，沿著路徑向南到達 ^Halondrus^。",
    ["After killing the ^Twin Empyreans^, take the southeastern exit from the room."] = "殺死^Twin Empyreans^後，從房間的東南出口走。",
    ["After landing below, follow the path to reach ^Scalecommander Sarkareth^."] = "在下方著陸後，沿著路徑到達^Scalecommander Sarkareth^。",
    ["After landing down below, take the downhill path and kill trash as you walk through the ^Helheim^ portal at the bottom."] = "在下面著陸後，走下坡路並在穿過底部的 ^Helheim^ 傳送門時殺死小怪。",
    ["After landing from ^Gust of Wind^, follow the path back out to ^The Primal Convergence^."] = "從 ^Gust of Wind^ 著陸後，沿著路徑返回 ^The Primal Convergence^。",
    ["After landing in ^Domination's Grasp^, proceed up the ramp. After some dialog, you can engage ^Anduin Wrynn^."] = "在 ^Domination's Grasp^ 著陸後，繼續走上坡道。經過一番對話後，您可以使用 ^Anduin Wrynn^。",
    ["After landing in ^Rift of Aln^, start killing trash. They will continue coming in waves until finally, you will meet ^Xavius^."] = "登陸^Rift of Aln^後，開始清理小怪。他們將繼續一波又一波地湧來，直到最後，您會遇到^Xavius^。",
    ["After landing in ^The Exhaust^, move forward to start the encounter with ^Imonar the Soulhunter^."] = "降落在^The Exhaust^後，繼續前進，開始與^Imonar the Soulhunter^的戰鬥。",
    ["After landing in ^The Traverse^, make your way to the bottom of the room by walking over a sequence of teleporting panels on the floor."] = "降落在 ^The Traverse^ 後，走過地板上的一系列傳送面板，到達房間底部。",
    ["After landing in the ^Genesis Cradle^, follow the path to ^Dausegne^."] = "登陸 ^Genesis Cradle^ 後，沿著路徑前往 ^Dausegne^。",
    ["After landing in the next area, go west to reach ^Shadow-Lord Iskar^."] = "降落在下一個區域後，向西到達^Shadow-Lord Iskar^。",
    ["After landing on the ship, make your way to the top of the ship and talk to ^Tandred Proudmoore^ to proceed."] = "登陸船上後，前往船頂並與 ^Tandred Proudmoore^ 交談以繼續。",
    ["After landing up top, follow the path around to the map exit labeled ^The Hive^."] = "到達頂部後，沿著周圍的路徑前往標記為 ^The Hive^ 的地圖出口。",
    ["After landing, clear trash in the water, then move up the short ramp and clear the remaining trash to engage ^Iron Maidens^."] = "著陸後，清除水中的小怪，然後沿著短坡道移動並清除剩餘的小怪以與^Iron Maidens^交戰。",
    ["After landing, continue ahead to find ^Durumu the Forgotten^. Clear all trash in the room to spawn the boss."] = "著陸後，繼續前進即可找到^Durumu the Forgotten^。清除房間中的所有小怪以出現 首領。",
    ["After landing, follow the path ahead to reach ^Sinestra^."] = "著陸後，沿著前面的路徑到達^Sinestra^。",
    ["After landing, follow the path down to the map exit labeled ^Maw of Gor'ma^."] = "著陸後，沿著路徑向下到達標記為 ^Maw of Gor'ma^ 的地圖出口。",
    ["After landing, follow the path east and then south to reach ^Valithria Dreamwalker^. As you approach, kill all trash to advance the NPCs."] = "落地後，沿路向東再向南前往^Valithria Dreamwalker^。靠近時清理所有敵人，讓NPC繼續推進。",
    ["After landing, follow the path east towards ^Valithria Dreamwalker^. As you approach her room, kill all trash to advance the NPCs. Walk around the outer edge to avoid pulling on the way to the elevator."] = "落地後，沿路向東前往^Valithria Dreamwalker^。接近她的房間時，清掉所有小怪以推進NPC。沿房間外圈前進，避免在前往電梯時引到怪。",
    ["After landing, follow the path to kill |cffF259C7(1)|r ^Volcanius^, then |cffF259C7(2)|r ^Eranog^."] = "落地後，按照路徑殺死|cffF259C7(1)|r ^Volcanius^，然後|cffF259C7(2)|r ^Eranog^。",
    ["After landing, follow the path to the final map exit labeled ^N'Zoth^. Kill adds on the bridge to spawn a portal at the end."] = "落地後，沿路前往標有 ^N'Zoth^ 的最後一個地圖出口。清理橋上的小怪，在橋盡頭召出傳送門。",
    ["After landing, kill ^Warlord Zon'ozz^ right in front of you."] = "著陸後，殺死你面前的^Warlord Zon'ozz^。",
    ["After landing, kill ^Yor'sahj^ in the middle of the room."] = "落地後，在房間中央殺死^Yor'sahj^。",
    ["After landing, move forward and click the ^Lightforged Beacon^ to be teleported to ^The Exhaust^."] = "落地後，向前移動，點擊^Lightforged Beacon^即可傳送至^The Exhaust^。",
    ["After landing, proceed down the steps to clear trash and begin the fight with ^High Tinker Mekkatorque^."] = "著陸後，繼續走下台階清除小怪，並與^High Tinker Mekkatorque^開始戰鬥。",
    ["After opening the door, proceed ahead to witness a lengthy dialog before engaging ^Garrosh Hellscream^."] = "開啟門後，在與 ^Garrosh Hellscream^ 交戰之前，繼續見證一段冗長的對話。",
    ["After reaching the bottom of the elevator, proceed north into the next area. Kill waves of adds until the northern door opens, and continue ahead to reach ^Sindragosa^. Clear trash to pull the mini-bosses."] = "到達電梯底部後，向北進入下一個區域。擊殺一波波敵人，直到北側大門開啟，再繼續前往^Sindragosa^。清理敵人以引出小首領。",
    ["After reaching the bottom of the elevator, take a right and follow the path to reach ^Maloriak^."] = "到達電梯底部後，右轉並沿著路徑到達^Maloriak^。",
    ["After reaching the bottom of the stairs, proceed forward to trigger a lengthy dialog, then engage ^Ra-den^."] = "到達樓梯底部後，繼續前進以觸發冗長的對話，然後接合^Ra-den^。",
    ["After reaching the top of the elevator, follow the path back to find ^Ra-den the Despoiled^."] = "到達電梯頂部後，沿著小路返回即可找到^Ra-den the Despoiled^。",
    ["After reaching the top of the elevator, follow the path to the east until you arrive on the ship. Talk to ^High Overlord Saurfang^ to start the encounter."] = "到達電梯頂部後，沿東側道路前往飛艇。與^High Overlord Saurfang^交談以開始戰鬥。",
    ["After reaching the top of the elevator, follow the path to the west until you arrive on the ship. Talk to ^Muradin Bronzebeard^ to start the encounter."] = "到達電梯頂部後，沿西側道路前往飛艇。與^Muradin Bronzebeard^交談以開始戰鬥。",
    ["After reaching the top of the elevator, make your way down the path and clear the trash to engage ^Vexiona^."] = "到達電梯頂部後，沿著路徑走下去並清除小怪以與 ^Vexiona^ 交戰。",
    ["After reaching the top of the stairs and opening a door, you will encounter ^The Coven of Shivarra^."] = "到達樓梯頂部並開啟門後，您將遇到^The Coven of Shivarra^。",
    ["After respawning in ^Chamber of the Moon^, proceed towards the group of NPCs and enter the descending stairwell behind them."] = "在 ^Chamber of the Moon^ 重生後，前往那群 NPC，並進入他們身後的下行樓梯間。",
    ["After returning to ^Wyrmrest Temple^, click ^Nethestrasz^, the dragon in front of you. Once you reach the top, click the portal to ^Travel to the Eye of Eternity^."] = "返回^Wyrmrest Temple^後，點擊前面的龍^Nethestrasz^。到達頂部後，點擊通往 ^Travel to the Eye of Eternity^ 的傳送門。",
    ["After returning to ^Wyrmrest Temple^, click ^Nethestrasz^, the dragon in front of you. Once you reach the top, wait on a lengthy dialog and click the portal to ^Travel to the Eye of Eternity^."] = "返回^Wyrmrest Temple^後，點擊前面的龍^Nethestrasz^。到達頂部後，等待一個冗長的對話框，然後點擊通往 ^Travel to the Eye of Eternity^ 的傳送門。",
    ["After returning to ^Wyrmrest Temple^, click on ^Eiendormi^, the dragon on the right."] = "返回^Wyrmrest Temple^後，點擊右側的龍^Eiendormi^。",
    ["After returning to the ^Halls of the Chosen^, follow the path all the way north to kill ^Radiance of Azshara^. Clear all the trash to start the encounter."] = "返回^Halls of the Chosen^後，沿著小路一路向北殺死^Radiance of Azshara^。清除所有小怪以開始戰鬥。",
    ["After returning to the ^Halls of the Chosen^, walk straight ahead to kill a couple ^Azsh'ari Channelers^ and click the ^Font of Power^."] = "返回^Halls of the Chosen^後，直走殺死一對^Azsh'ari Channelers^，然後點擊^Font of Power^。",
    ["After returning to the central hub, approach the middle of the room and interact with the ^Nightmare Iris^ to reach ^Moonglade^."] = "返回中心樞紐後，接近房間中央並與^Nightmare Iris^互動以到達^Moonglade^。",
    ["After returning to the central hub, continue clockwise through the next portal to reach ^Mulgore^."] = "返回中心樞紐後，繼續順時針穿過下一個傳送門到達^Mulgore^。",
    ["After returning to the central hub, talk to ^Malfurion^ then interact with the ^Nightmare Iris^ to continue."] = "返回中心樞紐後，與 ^Malfurion^ 交談，然後與 ^Nightmare Iris^ 交互以繼續。",
    ["After returning to the entrance, take the southeast path towards ^The Plague Quarter^."] = "返回入口後，沿東南路徑前往 ^The Plague Quarter^。",
    ["After returning to the main courtyard, follow the path all the way to the far southeast of the map to reach ^Krosus^."] = "返回主庭院後，沿著小路一直走到地圖最東南方，即可到達^Krosus^。",
    ["After some dialog, kill the trash wave that spawns, and ^Kargath Bladefist^ will enter the ring."] = "經過一番對話後，殺死產生的小怪波，^Kargath Bladefist^ 將進入環。",
    ["After spawning, cross the chasm using the ^Lightforged Teleport Pod^. Stay to the left when you reach the intersection, and follow the path to interact with a ^Portal^."] = "出現後，使用 ^Lightforged Teleport Pod^ 跨越鴻溝。到達十字路口時靠左行駛，然後沿著路徑與 ^Portal^ 互動。",
    ["After surfacing from the water, follow the path around to reach ^The Queen's Court^."] = "從水面浮出水面後，沿著周圍的小路到達^The Queen's Court^。",
    ["After switching to Alliance, follow the path up the stairs and around to the map exit labeled ^Halls of Opulence^. Jump in the hole at the end of the path."] = "切換到聯盟後，沿著樓梯向上並繞過標記為 ^Halls of Opulence^ 的地圖出口。跳進路盡頭的洞裡。",
    ["After taking the portal into ^The Last Prison^, you will watch some lengthy dialog then click the ^Titan Console^ in front of you to engage ^Queen Azshara^."] = "將傳送門進入 ^The Last Prison^ 後，您將看到一些冗長的對話框，然後點擊您前面的 ^Titan Console^ 以參與 ^Queen Azshara^。",
    ["After taking the portal, follow the long, linear path towards the next map exit labeled ^Elarian Sanctuary^."] = "進入傳送門後，沿著長長的線性路徑前往下一個標記為 ^Elarian Sanctuary^ 的地圖出口。",
    ["After taking the portal, follow the path around to find ^Twin Ogron^. Clear trash to start the encounter."] = "進入傳送門後，沿著周圍的路徑找到^Twin Ogron^。清除小怪以開始戰鬥。",
    ["After taking the portal, follow the path around to reach ^Kel'Thuzad^."] = "進入傳送門後，沿著周圍的路徑到達^Kel'Thuzad^。",
    ["After taking the portal, move ahead to clear trash to open the door and reach the final boss, ^Imperator Mar'gok^."] = "進入傳送門後，繼續清理小怪以開啟門並到達最終 首領 ^Imperator Mar'gok^。",
    ["After taking the portal, you will arrive in ^Destructor's Rise^. On ^Mythic^, do NOT kill the ^Fel Iron Summoners^. Just tag them, and let ^Mannoroth^ kill them or you could bug the encounter. On other difficulties, kill the ^Fel Iron Summoners^ to begin the fight."] = "進入傳送門後，您將到達^Destructor's Rise^。在 ^Mythic^ 上，請勿殺死 ^Fel Iron Summoners^。只需標記它們，然後讓 ^Mannoroth^ 殺死它們，否則您可能會在戰鬥中遇到麻煩。在其他困難上，殺死 ^Fel Iron Summoners^ 即可開始戰鬥。",
    ["After taking the teleport, follow the path to reach ^Portal Keeper Hasabel^."] = "進行傳送後，沿著路徑到達^Portal Keeper Hasabel^。",
    ["After taking the teleport, make your way for the right-most exit labeled ^Verdant Terrace^."] = "進行傳送後，前往最右側標有 ^Verdant Terrace^ 的出口。",
    ["After taking the teleport, you will land right in front of ^Archimonde^. Kill him!"] = "進行傳送後，您將降落在 ^Archimonde^ 的正前方。殺了他！",
    ["After taking the teleporter to ^Nightcloak Sanctum^, follow the path around to the ^Stone Legion Generals^. Clear trash to start the encounter."] = "乘坐傳送器到達 ^Nightcloak Sanctum^ 後，沿著路徑前往 ^Stone Legion Generals^。清除小怪以開始戰鬥。",
    ["After teleporting back to ^The Grand Walk^, follow the path up to where you killed ^Shriekwing^ (again). After some dialog, ^Sludgefist^ will jump down to fight."] = "傳送回 ^The Grand Walk^ 後，沿著路徑前往你殺死 ^Shriekwing^ 的地方（再次）。一番對話後，^Sludgefist^會跳下來戰鬥。",
    ["After teleporting to ^Sapphiron's Lair^, proceed ahead to engage ^Sapphiron^."] = "傳送到 ^Sapphiron's Lair^ 後，繼續直行並與 ^Sapphiron^ 交戰。",
    ["After teleporting, click the ^Orb of Naxxramas^ right next to you."] = "傳送後，點擊身旁的 ^Orb of Naxxramas^。",
    ["After teleporting, follow the path ahead and take a left before you reach the stairs. Continue down the path to reach ^The Assembly of Iron^. See special note for |cffF259C7Hard Mode|r."] = "傳送後沿前方道路前進，在到達樓梯前左轉。繼續沿路前往^The Assembly of Iron^。請查看|cffF259C7困難模式|r特別提示。",
    ["After teleporting, follow the path to ^Eye of the Jailer^ and clear all trash on his platform. To reach the far side, walk to the pile of chains and use the extra action button"] = "傳送後，沿著路徑前往 ^Eye of the Jailer^ 並清除其平台上的所有小怪。要到達遠端，請走到鏈條堆處並使用額外的操作按鈕",
    ["After teleporting, go north and take a right before the stairs. Follow the path around until you reach a console called ^Celestial Planetarium Access^. Click it to open the door to ^Algalon the Observer^."] = "傳送後向北走，在樓梯前右轉。沿路前進，直到找到名為^Celestial Planetarium Access^的控制台。點擊它開啟通往^Algalon the Observer^的門。",
    ["After teleporting, proceed ahead to witness a lengthy dialog before engaging ^Garrosh Hellscream^."] = "傳送後，在與 ^Garrosh Hellscream^ 交戰之前，繼續見證一段冗長的對話。",
    ["After teleporting, proceed forward and click on one of the ^Lightforged Warframes^ to be flown to the next area."] = "傳送後，繼續前進並點擊其中一個^Lightforged Warframes^即可飛到下一個區域。",
    ["After teleporting, proceed to the center of the ring and step on the teleporter."] = "傳送後前往環形區域中央，站上傳送器。",
    ["After teleporting, take the northwest exit toward ^The Construct Quarter^."] = "傳送後，從西北出口前往 ^The Construct Quarter^。",
    ["After teleporting, take the southwest path towards ^The Military Quarter^."] = "傳送後，沿西南路徑前往 ^The Military Quarter^。",
    ["After teleporting, take the spiral stairwell down in the middle of the room."] = "傳送後，沿著房間中間的螺旋樓梯走下去。",
    ["After teleporting, travel southwest to the ^Hall of Memories^."] = "傳送後向西南前往^Hall of Memories^。",
    ["After the first trash pack of scorpions, there will be a door opened to the right at the end of the hallway. Inside the room, you will find a teleporter that will allow you to teleport to:\n  - Palace Entrance (^Spellblade Aluriel^)\n  - Palace Courtyard (^Krosus^)\n  - Nightspire (^Elisande^)\n\nNote: RetroRuns only has the route built for Elisande at this time."] = "清理第一組蠍子小怪後，走廊盡頭右側會開啟一扇門。房間內有一個傳送器，可將你送往：\n  - 宮殿入口（^Spellblade Aluriel^）\n  - 宮殿庭院（^Krosus^）\n  - 暗夜之塔（^Elisande^）\n\n注意：RetroRuns 目前只提供通往艾莉珊德的路線。",
    ["After the teleport, you should be standing across from ^Fyrakk^. Approach him to start the encounter."] = "傳送後，您應該站在 ^Fyrakk^ 對面。接近他開始戰鬥。",
    ["After the tram stops, exit north and follow the path straight ahead to reach ^Mimiron^. See special note for |cffF259C7Hard Mode|r."] = "軌道車停下後，從北側下車並沿路直行前往^Mimiron^。請查看|cffF259C7困難模式|r特別提示。",
    ["After walking through the door, follow the path to ^Paragons of the Klaxxi^. Clear trash and click ^Mantid Amber^ in the middle of the room to start the encounter."] = "穿過門後，沿著路徑前往^Paragons of the Klaxxi^。清除小怪並點擊房間中間的 ^Mantid Amber^ 開始戰鬥。",
    ["After walking through the portal into ^Grizzly Hills^, follow the path around to find ^Ursoc^."] = "穿過傳送門進入^Grizzly Hills^後，沿著周圍的路徑找到^Ursoc^。",
    ["After walking through the portal, continue on the path and walk through the second portal to ^The Emerald Nightmare^."] = "穿過傳送門後，繼續沿著路徑走，穿過第二個傳送門到達^The Emerald Nightmare^。",
    ["After you land, enter the room and clear the trash to spawn ^Echo of Neltharion^."] = "著陸後，進入房間並清除小怪以出現 ^Echo of Neltharion^。",
    ["After you reach the next area, go downstairs and kill trash to begin the fight against ^High Tinker Mekkatorque^."] = "到達下一個區域後，下樓殺死小怪，開始與^High Tinker Mekkatorque^的戰鬥。",
    ["After zoning in, beware the legendary elevator boss! Go down to reach the next area, then take the southern path to ^Hydross the Unstable^."] = "進入副本後，小心傳說中的電梯首領！下到下一區域，然後沿南側路線前往 ^Hydross the Unstable^。",
    ["After zoning in, beware the legendary elevator boss! Go down to reach the next area. Take a left when you reach ^Hydross the Unstable^ and follow the path all the way around until you reach the ^Lady Vashj Bridge Console^. Click the console to open the bridge, then cross it to reach the final boss, ^Lady Vashj^."] = "進入副本後，小心傳說中的電梯首領！下到下一區域。抵達 ^Hydross the Unstable^ 後左轉，沿路繞一整圈直到抵達 ^Lady Vashj Bridge Console^。點擊控制台打開橋樑，然後過橋前往最終首領 ^Lady Vashj^。",
    ["After zoning in, click ^Blackrock Artifact^ on either side of the bridge, and it will open the gate leading across the bridge. Go forward and follow the route across the bridge."] = "進入副本後，點擊橋兩側的^Blackrock Artifact^，它將開啟通往橋的大門。向前走，沿著過橋的路線走。",
    ["After zoning in, click ^The Focusing Iris^ at the center of the platform to start the encounter with ^Malygos^."] = "進入副本後，點擊平台中央的 ^The Focusing Iris^，開始與 ^Malygos^ 的戰鬥。",
    ["After zoning in, click the ^Scroll of Past Deeds^ on the wall to skip ahead to ^Garrosh^. It's on the wall next to ^Lorewalker Cho^."] = "進入副本後，點擊牆上的 ^Scroll of Past Deeds^ 以跳至 ^Garrosh^。它位於 ^Lorewalker Cho^ 旁邊的牆上。",
    ["After zoning in, click the portal on the right for ^Destructor's Rise^ to be teleported to ^Mannoroth^."] = "進入副本後，點擊右側傳送門將^Destructor's Rise^傳送至^Mannoroth^。",
    ["After zoning in, click the portal to ^Wyrmrest Summit^ right in front of you."] = "進入副本後，點擊您面前的 ^Wyrmrest Summit^ 的傳送門。",
    ["After zoning in, continue ahead to find ^Durumu the Forgotten^. Clear all trash in the room to spawn the boss."] = "進入副本後，繼續前進找到^Durumu the Forgotten^。清除房間中的所有小怪以出現 首領。",
    ["After zoning in, continue following the linear path to reach the map exit labeled ^The Nighthold^."] = "進入副本後，繼續沿著線性路徑到達標記為 ^The Nighthold^ 的地圖出口。",
    ["After zoning in, continue up the stairwell towards the map exit labeled ^Halls of Opulence^. Jump in the hole when you reach the end of the path."] = "進入副本後，繼續沿樓梯間前往標有 ^Halls of Opulence^ 的地圖出口。當你到達路徑的盡頭時，跳進洞裡。",
    ["After zoning in, enter the room on the left and enter the portal at the map exit labeled ^Elunaria^."] = "進入副本後，進入左側的房間，進入標有^Elunaria^的地圖出口處的傳送門。",
    ["After zoning in, follow the linear path all the way to ^Kalecgos^."] = "進入副本後，沿直線路線一直前往 ^Kalecgos^。",
    ["After zoning in, follow the linear path to ^Halfus Wyrmbreaker^."] = "進入副本後，沿著線性路徑到達 ^Halfus Wyrmbreaker^。",
    ["After zoning in, follow the linear path to ^Lorewalker Cho^. Speak to him to trigger a series of trash encounters."] = "進入副本後，沿著線性路徑到達 ^Lorewalker Cho^。與他交談會引發一系列小怪戰鬥。",
    ["After zoning in, follow the linear path to find the first boss, ^Garothi Worldbreaker^."] = "進入副本後，沿著線性路徑找到第一個首領，^Garothi Worldbreaker^。",
    ["After zoning in, follow the linear path to reach ^Imperial Vizier Zor'lok^. Clear all trash in his room to start the fight."] = "進入副本後，沿著線性路徑到達^Imperial Vizier Zor'lok^。清理他房間裡的所有小怪，開始戰鬥。",
    ["After zoning in, follow the linear path up the ramps until you reach ^High Warlord Naj'entus^."] = "進入副本後，沿直線路線上坡，直到抵達 ^High Warlord Naj'entus^。",
    ["After zoning in, follow the main path to ^Vigilant Guardian^."] = "進入副本後，沿著主路徑前往 ^Vigilant Guardian^。",
    ["After zoning in, follow the path ahead to reach ^Za'qul^."] = "進入副本後，沿著前面的路到達^Za'qul^。",
    ["After zoning in, follow the path all the way back to ^Onyxia^."] = "進入副本後，沿路一直走到最深處，前往 ^Onyxia^。",
    ["After zoning in, follow the path around a few turns and up some stairs, killing trash on your way to ^Malkorok^."] = "進入副本後，沿著小路轉幾個彎，爬上一些樓梯，在前往 ^Malkorok^ 的路上消滅小怪。",
    ["After zoning in, follow the path around and up some stairs to reach the first boss, ^The Prophet Skeram^."] = "進入副本後，沿路繞行並上幾段樓梯，前往第一個首領^The Prophet Skeram^。",
    ["After zoning in, follow the path around to ^Hellfire High Council^."] = "進入副本後，沿著路徑前往 ^Hellfire High Council^。",
    ["After zoning in, follow the path around to find ^Ursoc^."] = "進入副本後，沿著周圍的路徑找到^Ursoc^。",
    ["After zoning in, follow the path straight ahead to engage ^Sivara^."] = "進入副本後，沿著路徑一直向前行駛以接合^Sivara^。",
    ["After zoning in, follow the path straight ahead to find and kill ^The Restless Cabal^."] = "進入副本後，沿著路徑一直向前尋找並殺死^The Restless Cabal^。",
    ["After zoning in, follow the path through ^Al'ar^'s room and continue north until you reach ^Kael'thas Sunstrider^."] = "進入副本後，沿路穿過 ^Al'ar^ 的房間並繼續往北，直到抵達 ^Kael'thas Sunstrider^。",
    ["After zoning in, follow the path to ^Gnarlroot^. Clear the trash around him to start the encounter."] = "進入副本後，沿著路徑前往 ^Gnarlroot^。清理他周圍的小怪以開始戰鬥。",
    ["After zoning in, follow the path to ^Lucifron^."] = "進入副本後，沿路前往^Lucifron^。",
    ["After zoning in, follow the path to ^Maw of Gor'ma^."] = "進入副本後，沿著路徑前往 ^Maw of Gor'ma^。",
    ["After zoning in, follow the path to the right and make your way down a spiral ramp."] = "進入副本後，沿著右側的路徑走下螺旋坡道。",
    ["After zoning in, follow the path to the right, and make your way towards the map exit labeled ^Defiant Ramparts^."] = "進入副本後，沿著右側的路徑行駛，前往標有 ^Defiant Ramparts^ 的地圖出口。",
    ["After zoning in, follow the southern path to reach ^Magtheridon^."] = "進入副本後，沿南側路線前往 ^Magtheridon^。",
    ["After zoning in, go downstairs and kill trash to begin the fight against ^High Tinker Mekkatorque^."] = "進入副本後，下樓殺死小怪，開始對抗^High Tinker Mekkatorque^。",
    ["After zoning in, go left to find ^Fel Lord Zakuun^."] = "進入副本後，向左走即可找到^Fel Lord Zakuun^。",
    ["After zoning in, go straight ahead and clear all trash to spawn ^Kazzara^."] = "進入副本後，繼續前進並清除所有小怪以出現 ^Kazzara^。",
    ["After zoning in, go straight ahead to engage ^Sire Denathrius^."] = "進入副本後，直接前往^Sire Denathrius^。",
    ["After zoning in, go to the West platform to start the fight with ^Conclave of the Wind^."] = "進入副本後前往西平台與^Conclave of the Wind^開始戰鬥。",
    ["After zoning in, go up the stairs to the right to reach the ^Omnotron Defense System^."] = "劃分區域後，沿右側樓梯到達^Omnotron Defense System^。",
    ["After zoning in, go west to reach ^Shadow-Lord Iskar^."] = "進入副本後，向西到達^Shadow-Lord Iskar^。",
    ["After zoning in, head down the stairs and move straight ahead to engage ^Immerseus^."] = "劃分區域後，下樓並向前直行以與^Immerseus^交戰。",
    ["After zoning in, head for the map exit labeled ^The Scorched Hall^."] = "進入副本後，前往標有 ^The Scorched Hall^ 的地圖出口。",
    ["After zoning in, head for the map exit labeled ^Verdant Terrace^."] = "進入副本後，前往標有 ^Verdant Terrace^ 的地圖出口。",
    ["After zoning in, head straight ahead and follow the route across the bridge."] = "進入副本後，一直向前，沿著路線過橋。",
    ["After zoning in, head through the door and proceed to the exit marked on the map."] = "進入副本後，穿過門，前往地圖上標記的出口。",
    ["After zoning in, head to the right wing to engage ^Argaloth^."] = "劃分區域後，前往右翼與^Argaloth^交戰。",
    ["After zoning in, interact with the dragon to be flown to ^Tindral Sageswift, Seer of the Flame^."] = "進入副本後，與龍互動，飛向^Tindral Sageswift, Seer of the Flame^。",
    ["After zoning in, jump in the purple portal in front of you."] = "進入副本後，跳進你面前的紫色傳送門。",
    ["After zoning in, jump into ^The Festering Core^ to fight ^Mythrax the Unraveler^."] = "進入副本後，跳入 ^The Festering Core^ 與 ^Mythrax the Unraveler^ 戰鬥。",
    ["After zoning in, make your way down the long path to find ^Kin'garoth^."] = "劃分區域後，沿著漫長的道路尋找^Kin'garoth^。",
    ["After zoning in, make your way down the path in front of you. When you can, hang a left and work your way around to ^Beth'tilac^."] = "進入副本後，沿著前面的路走。如果可以，請向左轉並繞行至 ^Beth'tilac^。",
    ["After zoning in, make your way to the other end of the room. Open the door to find ^Jin'rokh the Breaker^."] = "進入副本後，前往房間的另一端。開啟門找到^Jin'rokh the Breaker^。",
    ["After zoning in, make your way up the path and stay to the right and find the map exit labeled ^The Ritual Chamber^."] = "劃分區域後，沿著路徑向上走，靠右行駛，找到標有 ^The Ritual Chamber^ 的地圖出口。",
    ["After zoning in, move ahead and follow the north path out of ^Shriekwing^'s room and go down the stairs. Kill the trash, and ^General Draven^ will come open the gate. Kill a few trash mobs then engage ^Huntsman Altimor^."] = "進入副本後，繼續前進，沿著北邊的小路走出^Shriekwing^的房間，下樓梯。殺死小怪，^General Draven^ 就會開啟大門。殺死一些小怪小怪，然後與^Huntsman Altimor^交戰。",
    ["After zoning in, move ahead and kill the trash to begin the encounter with ^Protectors of the Endless^."] = "劃分區域後，繼續前進並殺死小怪，開始與 ^Protectors of the Endless^ 的戰鬥。",
    ["After zoning in, move ahead to clear trash to open the door and reach the final boss, ^Imperator Mar'gok^."] = "劃分區域後，繼續清理小怪以開啟門並到達最終 首領 ^Imperator Mar'gok^。",
    ["After zoning in, move ahead to find ^The Stone Guard^."] = "進入副本後，繼續尋找 ^The Stone Guard^。",
    ["After zoning in, move forward and take your first left to reach ^Koralon the Flame Watcher^."] = "進入副本後向前走，在第一個路口左轉前往^Koralon the Flame Watcher^。",
    ["After zoning in, move forward and take your first left to reach ^Skorpyron^."] = "劃分區域後，向前行駛並在第一個路口左轉即可到達 ^Skorpyron^。",
    ["After zoning in, move up the stairwell and follow the path to open a masked gate."] = "進入副本後，沿著樓梯井向上移動，沿著小路開啟一扇遮蔽的大門。",
    ["After zoning in, proceed across the bridge. On the beach, your goal is to destroy (7) ^Kor'kron Cannons^. Click the ^Spike Mines^ next to each cannon to destroy them."] = "進入副本後，繼續過橋。在海灘上，您的目標是摧毀 (7) ^Kor'kron Cannons^。點擊每門大炮旁邊的 ^Spike Mines^ 來摧毀它們。",
    ["After zoning in, proceed ahead into ^Shriekwing^'s room and take the southern map exit labeled ^Halls of the Faithful^."] = "劃分區域後，繼續前進進入 ^Shriekwing^ 的房間，並從標記為 ^Halls of the Faithful^ 的南面出口離開。",
    ["After zoning in, proceed ahead to ^Al'ar^. You may need to walk up a ramp to pull the boss."] = "進入副本後，往前前往 ^Al'ar^。你可能需要走上斜坡才能開怪。",
    ["After zoning in, proceed ahead to ^High King Maulgar^."] = "進入副本後，往前前往 ^High King Maulgar^。",
    ["After zoning in, proceed ahead to ^Maiden of Vigilance^."] = "進入副本後，繼續前往 ^Maiden of Vigilance^。",
    ["After zoning in, proceed ahead to engage ^Aggramar^."] = "進入副本後，繼續參與 ^Aggramar^。",
    ["After zoning in, proceed ahead to the ^Captain's Quarters^ entrance on the map. Inside the ^Captain's Quarters^, take your first right to go up a short stairwell."] = "進入副本後，繼續前往地圖上的 ^Captain's Quarters^ 入口。在 ^Captain's Quarters^ 內，在第一個路口右轉，走上一個短樓梯間。",
    ["After zoning in, proceed down the first hallway and clear the scorpion trash to open a door on your right. Click the ^Suramar Portal^ and teleport to the ^Nightspire^."] = "進入副本後，沿著第一個走廊前進，清除蠍子小怪，開啟右邊的門。點擊 ^Suramar Portal^ 並傳送到 ^Nightspire^。",
    ["After zoning in, proceed forward and clear the slimes to begin the encounter with ^Nythendra^."] = "劃分區域後，繼續前進並清除史萊姆，開始與 ^Nythendra^ 的戰鬥。",
    ["After zoning in, proceed forward out of ^The Coliseum^."] = "進入副本後，繼續走出 ^The Coliseum^。",
    ["After zoning in, proceed straight ahead to ^Champion of the Light^."] = "進入副本後，直行至^Champion of the Light^。",
    ["After zoning in, proceed straight ahead to ^Lady Ashvane^."] = "進入副本後，直行至^Lady Ashvane^。",
    ["After zoning in, proceed straight ahead to ^Razorgore^. |cffF259C7CAUTION!|r Do not attack ^Razorgore^ directly. Review the note!"] = "進入副本後，直走前往^Razorgore^。|cffF259C7小心！|r 不要直接攻擊^Razorgore^。請閱讀提示！",
    ["After zoning in, proceed straight ahead to engage ^Goroth^."] = "進入副本後，繼續直行前往^Goroth^。",
    ["After zoning in, proceed straight ahead to engage ^Magmorax^. Kill trash to start the encounter."] = "進入副本後，繼續向前行駛以接合^Magmorax^。殺死小怪來開始戰鬥。",
    ["After zoning in, proceed straight ahead to engage ^Morchok^."] = "進入副本後，繼續直行前往^Morchok^。",
    ["After zoning in, proceed straight ahead to engage ^Tortos^."] = "進入副本後，繼續直行前往^Tortos^。",
    ["After zoning in, proceed straight ahead to the first boss room. Kill trash to start the encounter with ^Champion of the Light^."] = "進入副本後，徑直前往第一個首領房間。殺死小怪以開始與 ^Champion of the Light^ 的戰鬥。",
    ["After zoning in, proceed straight ahead until you reach ^Lord Marrowgar^."] = "進入副本後一直向前，直到到達^Lord Marrowgar^。",
    ["After zoning in, proceed up to the left and work your way through the ^Livery Stables^ until you reach ^Attumen the Huntsman^."] = "進入副本後，往左上方前進，穿過 ^Livery Stables^，直到抵達 ^Attumen the Huntsman^。",
    ["After zoning in, read the ^Scroll of Past Deeds^ beside ^Lorewalker Cho^ to skip straight to ^Garrosh Hellscream^.\nThe scroll unlocks for your whole account once any character has defeated Garrosh."] = "進入副本後，閱讀 ^Scroll of Past Deeds^（位於 ^Lorewalker Cho^ 旁）即可直接跳到 ^Garrosh Hellscream^。\n任何角色擊敗卡爾洛斯後，該卷軸就會為整個帳號解鎖。",
    ["After zoning in, run up the stairs straight ahead to engage ^The Demonic Inquisition^."] = "劃分區域後，徑直跑上樓梯與^The Demonic Inquisition^交戰。",
    ["After zoning in, start killing trash. They will continue coming in waves until finally, you will meet ^Xavius^."] = "進入副本後，開始消滅小怪。他們將繼續一波又一波地湧來，直到最後，您會遇到^Xavius^。",
    ["After zoning in, take a left and head towards ^The Black Forge^. Take the elevator down."] = "劃分區域後，左轉並朝 ^The Black Forge^ 方向行駛。乘電梯下去。",
    ["After zoning in, take a right and follow the path to ^Kurinnaxx^."] = "進入副本後，右轉並沿路前往^Kurinnaxx^。",
    ["After zoning in, take a right and head for the map exit labeled ^Gallery of Failures^."] = "進入副本後，右轉前往標有 ^Gallery of Failures^ 的地圖出口。",
    ["After zoning in, take the escalator all the way up to engage ^Odyn^."] = "進入副本後，乘自動扶梯一路向上即可到達^Odyn^。",
    ["After zoning in, take the middle path labeled ^The Clutchwarren^."] = "進入副本後，走標記為 ^The Clutchwarren^ 的中間路徑。",
    ["After zoning in, take the northeast path to ^The Arachnid Quarter^."] = "進入副本後，沿東北路徑前往 ^The Arachnid Quarter^。",
    ["After zoning in, take the northeastern path towards the ^Iron Assembly^."] = "劃分區域後，沿東北方向前往 ^Iron Assembly^。",
    ["After zoning in, talk to ^Barrett Ramsey^ and then approach the middle ring to start the battle against ^The Northrend Beasts^."] = "進入副本後，與^Barrett Ramsey^交談，再靠近中央圓環，開始對陣^The Northrend Beasts^的戰鬥。",
    ["After zoning in, talk to ^Brann Bronzebeard^ to begin the encounter with ^Flame Leviathan^. See special note for |cffF259C7Hard Mode|r."] = "進入副本後，與^Brann Bronzebeard^交談以開始^Flame Leviathan^戰鬥。請查看|cffF259C7困難模式|r特別提示。",
    ["After zoning in, talk to ^Gharg^ and tell him you're ready. He will send you up an elevator into ^The Coliseum^."] = "劃分區域後，與 ^Gharg^ 交談並告訴他你已經準備好了。他將送您乘電梯前往^The Coliseum^。",
    ["After zoning in, talk to ^Wrathion^ to trigger a cutscene, then kill some adds to start the fight with ^Carapace of N'Zoth^."] = "進入副本後，與 ^Wrathion^ 交談以觸發過場動畫，然後殺死一些小怪以開始與 ^Carapace of N'Zoth^ 的戰鬥。",
    ["After zoning in, talk with ^Ensign Roberts^ to skip straight to ^Lady Jaina Proudmoore^."] = "進入副本後，與 ^Ensign Roberts^ 交談，直接跳至 ^Lady Jaina Proudmoore^。",
    ["After zoning in, talk with ^Otoye^ to skip straight to ^Lady Jaina Proudmoore^."] = "進入副本後，與 ^Otoye^ 交談，直接跳至 ^Lady Jaina Proudmoore^。",
    ["After zoning in, wait for the dialog to complete on the boat. You will be transported shortly."] = "進入副本後，等待船上對話完成。您很快就會被轉移。",
    ["After zoning in, wait for the dialog to complete. You will be transported shortly."] = "進入副本後，等待對話框完成。您很快就會被轉移。",
    ["After zoning in, walk straight ahead and kill the Tendrils to start the encounter with ^Taloc^."] = "進入副本後，徑直向前走並殺死捲鬚，開始與 ^Taloc^ 的戰鬥。",
    ["After zoning in, walk up the ramp in front of you to find ^Wind Lord Mel'jarak^."] = "劃分區域後，走上前面的坡道即可找到 ^Wind Lord Mel'jarak^。",
    ["After zoning in, you will find portals to your left/right depending on which skips you've unlocked.\n* Upper Citadel -> ^Shadow-Lord Iskar^\n* Destructor's Rise -> ^Mannoroth^\n\nNote: RetroRuns only has the route built for Mannoroth at this time."] = "進入副本後，左右兩側會根據你已解鎖的捷徑出現傳送門。\n* 上層堡壘 -> ^Shadow-Lord Iskar^\n* 毀滅者高地 -> ^Mannoroth^\n\n注意：RetroRuns 目前只提供通往瑪諾洛斯的路線。",
    ["After zoning into ^Crown of Gorgoa^, follow the path North to ^Guardian of the First Ones^."] = "划入 ^Crown of Gorgoa^ 後，沿著路徑向北前往 ^Guardian of the First Ones^。",
    ["After zoning into ^Domination's Grasp^, proceed up the ramp. After some dialog, you can engage ^Anduin Wrynn^."] = "划入 ^Domination's Grasp^ 後，繼續沿坡道行駛。經過一番對話後，您可以使用 ^Anduin Wrynn^。",
    ["After zoning into ^Genesis Cradle^, follow the path to ^Dausegne^."] = "分區到 ^Genesis Cradle^ 後，沿著路徑前往 ^Dausegne^。",
    ["After zoning into ^The Grand Design^, move straight ahead to ^The Jailer^'s platform and end this."] = "划入^The Grand Design^後，直接前往^The Jailer^平台並結束。",
    ["After zoning into ^The Primal Bulwark^, there are 3 paths available. Take the path on the right labeled ^The Vault Approach^."] = "分區到 ^The Primal Bulwark^ 後，有 3 條可用路徑。走右側標記為 ^The Vault Approach^ 的路徑。",
    ["After zoning into ^The Torment Chambers^, follow the path to ^Soulrender Dormazain^."] = "分區到 ^The Torment Chambers^ 後，沿著路徑前往 ^Soulrender Dormazain^。",
    ["After zoning into the landing area, take the left portal to zone into the raid."] = "進入降落區域後，走左側傳送門進入團隊副本。",
