    ["Proceed straight ahead to engage ^Sartharion^."] = "繼續直行，與 ^Sartharion^ 交戰。",
    ["Purchase ToC Tier 9 appearances:"] = "購買十字軍試煉T9外觀：",
    ["Quest reward from Highlord Mograine's chain; requires 50 Shadowfrost Shards from 25-player Heroic bosses."] = "大領主莫格萊尼任務線的獎勵；需要從25人英雄難度首領取得50個影霜裂片。",
    ["Quest reward from the legendary staff chain; its materials drop throughout Firelands."] = "傳奇法杖任務線的獎勵；材料會在火焰之地各處掉落。",
    ["Ragnaros defeated! Due to a Blizzard bug, it may take a moment for the game to register the kill. If your progress doesn't update after 10-15 seconds, /reload or re-log to force it."] = "已擊敗拉格納羅斯！由於遊戲錯誤，系統可能需要片刻才能記錄擊殺。如果 10-15 秒後進度仍未更新，請輸入 /reload 或重新登入以強制重新整理。",
