    ["Run around the room killing elites/vehicles until the encounter with ^Hellfire Assault^ begins."] = "在房間裡跑來跑去，殺死精英/車輛，直到遇到 ^Hellfire Assault^ 開始。",
    ["Run past the pond to find an exit portal among the trees."] = "跑過池塘，在樹林中找到出口。",
    ["Sarkareth additionally drops {item}, an omnitoken that exchanges for any tier slot. Not tracked here."] = "薩卡雷斯還會掉落 {item}，這是一種可兌換任意套裝部位的全能代幣。本插件不追蹤該物品。",
    ["Sarkareth also drops {item}, which starts the quest chain that rewards Nasz'uro, the Unbound Legacy (Evoker only)."] = "薩卡雷斯還會掉落 {item}，它會開啟一條任務線，最終獎勵“納茲烏羅，無拘傳承”（僅限喚魔師）。",
