    ["Teleporter then Boss"] = "傳送者然後是 首領",
    ["The goal is to collect (2) orbs from opposite sides of the room and deposit them into slots on each side of the boss. Next, the boss will become available to kill."] = "目標是從房間的相對兩側收集 (2) 個球體並將它們放入 首領 兩側的插槽中。接下來，首領將變得可供殺死。",
    ["The goal of the fight is to collect ^Felfire Munitions^ and run them to the ^Hellfire Cannons^. You collect munitions by killing ^Felfire-Imbued Siege Vehicles^ which will come in waves."] = "戰鬥的目標是收集 ^Felfire Munitions^ 並將它們運行到 ^Hellfire Cannons^。你可以通過殺死一波又一波的^Felfire-Imbued Siege Vehicles^來收集彈藥。",
    ["The only mechanic that matters anymore is his knockback. Position yourself so it launches you to the left or right platform. Kill adds on both platforms and return to middle. For next knockback, let it knock you to the upper middle platform. Finish the boss there!"] = "唯一重要的機制是他的擊退。調整好自己的位置，以便將您帶到左側或右側的平台。殺死兩個平台上的新增並返回到中間。對於下一次擊退，讓它把你擊到中上平台。乾掉那裡的首領！",
    ["There is a large egg on each side of ^Sinestra^. Attack the boss/whelps until the barriers drop from these two large eggs. Kill the 2 large eggs, then kill the boss."] = "^Sinestra^ 的每一面都有一個大雞蛋。攻擊 首領/幼崽，直到這兩個大蛋的障礙物掉落。殺掉2個大蛋，然後殺掉首領。",
    ["There is a Portal to Dalaran just south of you."] = "你的正南方有一個通往達拉然的傳送門。",
    ["These items are acquired by redeeming Qiraji tokens at the AQ20 entrance."] = "這些物品可在AQ20入口兌換其拉徽記取得。",
    ["These items are acquired by redeeming Qiraji tokens inside the temple, one piece per token."] = "這些物品可在神殿內兌換其拉徽記取得，每個徽記兌換一件。",
    ["This time, take the far-left exit to reach ^The Elemental Conclave^."] = "這次，從最左邊的出口到達^The Elemental Conclave^。",
