    ["Travel along the ledge into the next room. Stick to one side of the room to avoid overlapping auras, and click ^Suppression Devices^ to temporarily disable them as you move through the room."] = "沿平台邊緣進入下一個房間。貼著房間一側前進以避免光環重疊，並點擊^Suppression Devices^暫時關閉它們。",
