    ["Up to Xy'mox"] = "上樓前往賽‧墨克斯",
    ["Upon landing back in ^Halls of the Faithful^, follow the path to the right and ^Prince Renathal^ will guide you to a mirror portal. Take this teleport for a shortcut back to the main entrance lobby in ^The Grand Walk^."] = "返回 ^Halls of the Faithful^ 後，沿著右側的路徑前進，^Prince Renathal^ 將引導您到達鏡像傳送門。通過此傳送可以捷徑返回 ^The Grand Walk^ 的主入口大廳。",
    ["Upon reaching ^Pride's Prison^, follow the path to engage ^Sun King's Salvation^."] = "到達 ^Pride's Prison^ 後，按照路徑與 ^Sun King's Salvation^ 交戰。",
    ["Upon zoning in, go up the stairs into the first room and watch some dialog. After that, engage ^Shriekwing^."] = "進入副本後，上樓梯進入第一個房間並觀看一些對話。之後，參與^Shriekwing^。",
    ["Upon zoning in, talk to all 5 dragons. Then talk to ^Khadgar^ to begin the assault. Choose any dragon; doesn't matter."] = "劃分區域後，與所有 5 條龍交談。然後與 ^Khadgar^ 交談以開始攻擊。選擇任何一條龍；沒關係。",
    ["Upon zoning in, you will find ^Wrathion^ directly in front of you."] = "進入副本後，您會發現 ^Wrathion^ 就在您的前面。",
