    ["Upstairs to Grong"] = "樓上到格隆",
    ["Upstairs to Ko'ragh"] = "去科拉格樓上",
    ["Upstairs to Mirror"] = "樓上的鏡子",
    ["Upstairs to Precipice of Dreams"] = "通往夢想懸崖的樓上",
    ["Upstairs to Purloined Stores"] = "樓上被盜商店",
    ["Upstairs to The Clutchwarren"] = "上樓前往育巢區",
    ["Upstairs to the Right"] = "樓上右邊",
    ["Use Teleporter"] = "使用傳送器",
    ["Valeera on Left"] = "瓦麗拉（左）",
    ["Valiant Bressia"] = "Valiant Bressia",
    ["Valiant Laradia"] = "Valiant Laradia",
    ["Vent Behind Neltharion then Jump"] = "奈薩里奧身後的通風口，然後跳下",
    ["Vent"] = "通風口",
    ["Verdant Dreambreaker"] = "蒼翠破夢者",
    ["View special note"] = "查看特殊說明",
    ["Viscidus requires you to freeze him and then shatter him with physical/melee damage within a time limit. For most classes, soloing this will require gimmicky strategies involving special trinkets/toys. You can {skip} this boss if you don't have the kit or the patience for it."] = "Viscidus需要先被冰凍，再於限時內用物理/近戰傷害擊碎。對大多數職業而言，單刷需要特殊飾品/玩具等技巧。若沒有合適的裝備或耐心，可以{skip}這個首領。",
    ["Wait for transport"] = "等待運輸",
    ["Wait for Tsulong"] = "等待祖龍",
    ["Walk into (3) Floor Teleporters"] = "走進 (3) 層傳送器",
    ["Walk into the ^beam of light^ and click the ^Extra Action Button^ to trigger a cutscene. After the cutscene, go up the stairs and jump off the ledge."] = "走進^beam of light^並點擊^Extra Action Button^觸發過場動畫。過場動畫結束後，上樓梯並從壁架上跳下來。",
    ["Walk over anima orbs to collect them, and bring them to ^Prince Renathal^ to free him."] = "走過心能球收集它們，並將它們帶到 ^Prince Renathal^ 以釋放他。",
    ["Warden Thul'tok then Portal"] = "典獄長蘇托克和傳送門",
    ["Weapon Quest NPCs"] = "武器任務NPC",
    ["Weapons"] = "武器",
    ["West Exit"] = "西口",
    ["West exit"] = "西側出口",
    ["West stairwell"] = "西樓梯間",
    ["West then North"] = "先西後北",
    ["West through pipe"] = "往西穿過管道",
    ["West to Abyssal Throne"] = "西至深淵王座",
    ["West to Chimaeron"] = "向西至奇梅隆",
    ["West to Conclave"] = "西至議會",
    ["West to Gehennas"] = "向西前往Gehennas",
    ["West to Iron Juggernaut"] = "向西到鋼鐵主宰",
    ["West to Iskar"] = "向西至伊斯卡",
    ["West to Occu'thar"] = "向西至奧庫塔爾",
    ["West to Portal"] = "西至傳送門",
    ["West to Shek'zeer"] = "向西至謝克澤爾",
    ["West to Tectus"] = "西至泰克圖斯",
    ["West to The Queen's Court"] = "西至皇后法庭",
    ["West to World Soul"] = "西方世界靈魂",
    ["West to Za'qul"] = "向西至札奎爾",
    ["Western stairwell"] = "西樓梯間",
    ["Western Stairwell"] = "西側樓梯間",
    ["When feathers spawn near the boss, grab one. Mount up and follow him."] = "當 首領 附近出現羽毛時，抓住一根。上馬跟隨他。",
    ["When the boss shields, you must kill the adds to break his shield. Use Neltharion's various abilities (Rushing Darkness, Calamitous Strike) to break walls and reach the adds. You can attack the shielded adds once you have Corruption cast on you."] = "當首領護盾時，你必須殺死小怪才能打破他的護盾。使用耐薩里奧的各種能力（衝鋒黑暗、災難打擊）來打破牆壁並到達小怪。一旦你對你施放了腐蝕，你就可以攻擊受到護盾的小怪。",
    ["When the ship stops, talk to ^Ensign Roberts^ to continue."] = "當船停止時，與 ^Ensign Roberts^ 交談以繼續。",
    ["When you arrive in ^The Primal Convergence^, take the first path on the left labeled ^Quarry of Infusion^."] = "當您到達 ^The Primal Convergence^ 時，走左側第一條標記為 ^Quarry of Infusion^ 的路徑。",
    ["When you reach ^Un'Goro Crater^, follow the linear path to the back and kill ^Il'gynoth^."] = "當你到達^Un'Goro Crater^時，沿著線性路徑到後面並殺死^Il'gynoth^。",
    ["When you reach the bottom of the stairwell, cross the room and engage ^Maiden of Vigilance^."] = "當你到達樓梯井底部時，穿過房間並與 ^Maiden of Vigilance^ 交戰。",
    ["When you reach the bottom of the tunnels, go west into the room and find ^Silithid Royalty^."] = "到達隧道底部後，向西進入房間並找到^Silithid Royalty^。",
    ["When you reach the bottom, simply follow the path to ^Orgozoa^ and kill him."] = "當你到達底部時，只需沿著通往 ^Orgozoa^ 的路徑並殺死他即可。",
    ["When you reach the central hub, take the map exit labeled ^Mulgore^."] = "當您到達中心樞紐時，請從標有 ^Mulgore^ 的地圖出口離開。",
    ["When you reach the top of the staircase, you will go through a door and continue north to reach ^Sisters of the Moon^. For the next few areas, avoid the purple circular areas on the ground as they will stun you."] = "當您到達樓梯頂部時，您將穿過一扇門並繼續向北到達^Sisters of the Moon^。對於接下來的幾個區域，請避開地面上的紫色圓形區域，因為它們會讓你暈眩。",
    ["When you reach the top of the stairs, continue following the path to reach ^The Curator^."] = "抵達樓梯頂端後，繼續沿路前往 ^The Curator^。",
    ["When you reach the top of the stairwell, continue following the linear path to reach the map exit labeled ^The Nighthold^."] = "當您到達樓梯間頂部時，繼續沿著線性路徑到達標記為 ^The Nighthold^ 的地圖出口。",
    ["When you're back in the central hub, take the final portal towards ^Un'Goro Crater^."] = "當您回到中心樞紐後，進入通往 ^Un'Goro Crater^ 的最終傳送門。",
    ["With all (3) mini-bosses dead, approach the middle area to engage ^Halion^."] = "全部（3）個小首領死亡後，靠近中央區域與^Halion^交戰。",
    ["Work your way down the long southeast path towards ^Master's Terrace^."] = "沿漫長的東南路線往下，前往 ^Master's Terrace^。",
    ["Work your way through the next area, and kill ^Warden Thul'tok^ to spawn a portal. Walk through the portal."] = "穿過下一個區域，殺死 ^Warden Thul'tok^ 以出現一個傳送門。穿過傳送門。",
    ["Work your way up to ^Malfurion Stormrage^ and talk to him to open the ^Nightmare Iris^. Interact with it to skip ahead to ^Cenarius^."] = "一路走到 ^Malfurion Stormrage^ 並與他交談以開啟 ^Nightmare Iris^。與其交互以跳至 ^Cenarius^。",
    ["Work your way upstairs through ^The Vault Approach^ and you will enter ^The Clutchwarren^."] = "通過 ^The Vault Approach^ 上樓，您將進入 ^The Clutchwarren^。",
    ["Wrap around to ramp"] = "繞到斜坡",
    ["Wrathion then Trash"] = "怒西昂然後是小怪",
    ["Yields: %s"] = "可獲得：%s",
    ["You arrive at ^Pinnacle of Domination^ right in front of ^Sylvanas Windrunner^. Walk towards the boss to trigger dialog and start the encounter."] = "您到達 ^Pinnacle of Domination^ 就在 ^Sylvanas Windrunner^ 前面。走向首領觸發對話並開始戰鬥。",
    ["You can jump in the lava to die, and you will respawn at the entrance."] = "你可以跳進熔岩自殺，之後會在入口處復活。",
    ["You can just attack through his shield at this point. But if you need help, kill Nightmare Ichors near the boss to bring down his shield. When he becomes vulnerable, go inside and finish him off."] = "此時你可以直接穿透他的護盾攻擊。但若需要協助，請擊殺首領附近的夢魘膿液以解除護盾。當他變得脆弱時，進入內部將他擊敗。",
    ["You have reached the final boss, ^Argus the Unmaker^. Kill him!"] = "您已到達最終首領，^Argus the Unmaker^。殺了他！",
    ["You have reached the final encounter. Kill ^Gul'dan^!"] = "你們已經到達了最後的相遇。殺死^Gul'dan^！",
    ["You have to destroy the blast doors on both sides of the furnace. Go to one side, and let engineers come to you. Kill them, pick up their bombs, and use them by the door until the door \"dies\". Repeat process on the other side. After both doors are down, take down the elemental."] = "你必須摧毀熔爐兩側的爆破門。前往其中一側，讓工程師靠近你。擊殺他們、拾取炸彈，並在門旁使用，直到門的「生命值」歸零。另一側重複此流程。兩道門都倒下後，擊敗元素生物。",
    ["You must kill all 3 mini-bosses to spawn ^Halion^. Start with ^Baltharus the Warborn^ to the east."] = "必須擊殺全部3個小首領才能召喚^Halion^。先擊殺東側的^Baltharus the Warborn^。",
    ["You will find ^Broodlord Lashlayer^ at the end of the next room."] = "你會在下一個房間盡頭找到^Broodlord Lashlayer^。",
    ["You will have to bring his health down to zero several times. In each intermission, you must kill an add called Organ of Corruption to continue the fight."] = "你將不得不多次將他的生命值降至零。在每次中場休息時，你必須殺死一個名為腐化器官的小怪才能繼續戰鬥。",
    ["You will zone in right in front of ^Archimonde^. Kill him!"] = "您將位於 ^Archimonde^ 的正前方。殺了他！",
    ["Zone out first"] = "請先離開副本",
    ["{dot} = Base item, bought with gold\n"] = "{dot} = 基礎物品，使用金幣購買\n",
    ["{upArrow} = Trash drops can be upgraded to a Heroic appearance with {item}."] = "{upArrow} = 小怪掉落可使用{item}升級為英雄難度外觀。",
    ["|cff888888        * |r%s"] = "|cff888888        * |r%s",
    ["|cff888888     * %s: |r|cffffffff%s|r"] = "|cff888888     * %s: |r|cffffffff%s|r",
    ["|cff888888     * %s: |r|cffffffff%s|r|cff888888 for |r%s"] = "|cff888888     * %s: |r|cffffffff%s|r|cff888888 用於 |r%s",
    ["|cff888888  -> Redeem tokens at |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r"] = "|cff888888  -> 在此兌換徽記 |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r",
    ["|cff888888  -> Redeem tokens at |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r|cff888888 (|r|cffffffff%s|r|cff888888)|r"] = "|cff888888  -> 在此兌換徽記 |r|cffffffff%s|r|cff888888: |r|cffffffff%s|r|cff888888 (|r|cffffffff%s|r|cff888888)|r",
    ["|cff888888  -> |r|cffffffff%s|r|cff888888 -- |r|cffffffff%s|r"] = "|cff888888  -> |r|cffffffff%s|r|cff888888 -- |r|cffffffff%s|r",
    ["|cffF259C7(1)|r Click one of the Pterrordax to start the fight. |cffF259C7(2)|r Kill Brother/Sister. Killing too fast can bug the fight. |cffF259C7(3)|r Teleport to change boats and kill the other Brother/Sister. |cffF259C7(4)|r Teleport back to main platform and interrupt/kill the boss before he finishes casting Catastrophic Tides."] = "|cffF259C7(1)|r 點擊其中一隻翼手龍即可開始戰鬥。 |cffF259C7(2)|r 殺死兄弟/姐妹。擊殺太快可能會擾亂戰鬥。 |cffF259C7(3)|r 傳送換船並殺死其他兄弟/姐妹。 |cffF259C7(4)|r 在 首領 施放災難之潮之前傳送回主平台並打斷/殺死他。",
    ["|cffF259C7(1)|r Hit the boss until he runs into the next room. |cffF259C7(2)|r In the next room, your goal is to kill the Synthesis Growths sticking to the walls on both sides of the room. Kill slimes on the floor to clear walking paths. Pickup glowing orbs along the way to keep sanity up. |cffF259C7(3)|r After the Synthesis Growths are all killed, follow the boss into the next room to finish the encounter."] = "|cffF259C7(1)|r 打 首領 直到他跑進下一個房間。 |cffF259C7(2)|r 在隔壁房間，您的目標是殺死粘在房間兩側牆壁上的合成生長物。殺死地板上的史萊姆以清理人行道。沿途拾取發光的球體以保持理智。 |cffF259C7(3)|r 合成生長體全部被殺死後，跟隨首領進入下一個房間完成戰鬥。",
    ["|cffF259C7(1)|r Kill adds until a blue swirly portal (Mindgate) appears on the ground. Click it to be sent into the Mind of ^N'Zoth^. |cffF259C7(2)|r Note your location on the minimap, because your goal is to kill Psychus and return to your body as fast as possible and click it to return to the physical realm. |cffF259C7(3)|r Back outside, attack ^N'Zoth^. This phase may need to be repeated depending on speed. |cffF259C7(4)|r A waygate will spawn. Enter it to kill an add and return to ^N'Zoth^ and finish the fight."] = "|cffF259C7(1)|r 清理小怪，直到地面出現藍色漩渦傳送門（心靈之門）。點擊它進入 ^N'Zoth^ 的心智。 |cffF259C7(2)|r 記住自己在小地圖上的位置；你的目標是盡快擊殺賽古斯並返回自己的身體，然後點擊身體回到現實領域。 |cffF259C7(3)|r 返回外界後攻擊 ^N'Zoth^。根據擊殺速度，這個階段可能需要重複。 |cffF259C7(4)|r 隨後會出現一道傳送門。進入其中擊殺一名小怪，再返回 ^N'Zoth^ 完成戰鬥。",
    ["|cffF259C7(1)|r Watch for invasions on the minimap. Use Surge of Life to get around the map and defeat waves as they spawn. |cffF259C7(2)|r After clearing 2 waves, boss will emote that invaders are charging their weapons. This is your queue to walk over one of the teleports near the pull location to enter the ship. |cffF259C7(3)|r After entering the ship, kill the mob and then click all 4 crystals in each corner. Jump out of the ship and resume killing waves until the encounter completes."] = "|cffF259C7(1)|r 留意小地圖上的入侵。使用生命奔流在地圖上快速移動，並擊敗出現的敵軍波次。 |cffF259C7(2)|r 清除 2 波後，首領會發出表情訊息，表示入侵者正在為武器充能。此時走到開怪位置附近的任一傳送點上，進入飛船。 |cffF259C7(3)|r 進入飛船後，擊殺小怪，再點擊四個角落的所有 4 顆水晶。跳出飛船並繼續擊敗敵軍波次，直到戰鬥完成。",
    ["|cffF259C7HARD MODE:|r Allow (6) ^Saronite Vapors^ to spawn without killing them. This will spawn a ^Saronite Animus^ around the 3 minute mark. Defeat the Animus then defeat the boss."] = "|cffF259C7困難模式：|r讓（6）個^Saronite Vapors^出現，但不要擊殺。大約3分鐘時會生成一個^Saronite Animus^。先擊敗畸體，再擊敗首領。",
    ["|cffF259C7HARD MODE:|r Click the Big Red Button before starting the boss fight."] = "|cffF259C7困難模式：|r在開始首領戰前點擊大紅按鈕。",
    ["|cffF259C7HARD MODE:|r Kill him in under 2 minutes."] = "|cffF259C7困難模式：|r在2分鐘內將其擊殺。",
    ["|cffF259C7HARD MODE:|r Kill Steelbreaker last."] = "|cffF259C7困難模式：|r最後擊殺斷鋼者。",
    ["|cffF259C7HARD MODE:|r Leave the elders alive."] = "|cffF259C7困難模式：|r讓長者保持存活。",
    ["|cffF259C7HARD MODE:|r Wait for an add phase and destroy the heart."] = "|cffF259C7困難模式：|r等待小怪階段並摧毀心臟。",
    ["|cffF259C7Phase 1:|r Run through clouds to spawn Guardians. Kill them near Sara. |cffF259C7Phase 2:|r Kill adds until portals appear. Click one to go inside Yogg. |cffF259C7Phase 3:|r Kill all of the tentacles to open the path to Yogg's brain. Kill it to be returned to the outside where you can now attack Yogg directly.\n\n|cffF259C7HARD MODE:|r Kill the boss without accepting help from the keepers. Zero keepers is required for ^Mimiron's Head^."] = "|cffF259C7階段1：|r穿過雲霧召喚守護者，並在薩拉附近擊殺。|cffF259C7階段2：|r清理小怪直到傳送門出現，點擊一個進入尤格體內。|cffF259C7階段3：|r擊殺所有觸鬚，開啟通往尤格大腦的道路。摧毀大腦後會返回外部，此時可以直接攻擊尤格。\n\n|cffF259C7困難模式：|r不要接受守護者說明並擊敗首領。要獲得^Mimiron's Head^，必須是零守護者。",
    -- End route content translations

